\label{MMRZthm}
Let $u_0\in L^2(\mathbb{R}^d)$ satisfy $M(u_0)<M(Q)$. Then the solution of
\eqref{1.1} is global and scatters in both time directions.

\label{main1}
Let $d\geq3$ and let $u:I\times\mathbb{R}^d\to\mathbb{C}$ be a maximal-lifespan
strong $L^2$ solution of
\eqref{1.1} satisfying
\[
M(u)=M(Q),\qquad S_I(u)=\infty.
\]
Then exactly one of the following alternatives occurs:
\begin{enumerate}
\item $I=\mathbb{R}$ and $u$ is a solitary wave. More precisely, there exist
$\lambda>0$, $x_0,\xi\in\mathbb{R}^d$, and $\gamma\in[0,2\pi]$ such that
\begin{align}\label{soliton}
u(t,x)=e^{i\gamma-it|\xi|^2}e^{i\lambda^2t}e^{ix\cdot\xi}
\lambda^{d/2}Q\bigl(\lambda(x-2\xi t)-x_0\bigr).
\end{align}
\item $I=(-\infty,T)$ or $I=(T,\infty)$ for some $T\in\mathbb{R}$, and $u$ is
a pseudo-conformal transform of a solitary wave. More precisely, there
exist $\lambda>0$, $x_0,\xi\in\mathbb{R}^d$, and $\gamma\in[0,2\pi]$ such that
\begin{align}\label{pseudosoliton}
u(t,x)=\frac{\lambda^{d/2}}{|T-t|^{d/2}}e^{i\gamma}
e^{\frac{i|x-\xi|^2}{4(t-T)}}e^{-i\frac{\lambda^2}{t-T}}
Q\left(\frac{\lambda(x-\xi)-(T-t)x_0}{T-t}\right).
\end{align}
\end{enumerate}

\label{alcompact}
Suppose $u:I\times\mathbb{R}^d\to\mathbb{C}$ is a maximal-lifespan solution to \eqref{1.1} satisfying $M(u)=M(Q)$.
If $u$ blows up forward in time, then $u$ is almost periodic on $[0,\sup I)$.  Similarly, if $u$ blows up backward in time, then $u$ is almost periodic on $(\inf I,0]$.

\label{basicp} We have

\begin{itemize}

\item[$(i)$] For $1<r<\infty$, $0<\rho \leq \infty$, and $\theta>0$, $\||f|^\theta\|_{L^{r,\rho}} = \|f\|^\theta_{L^{\theta r, \theta \rho}}$.

\item[$(ii)$]  $|x|^{-2} \in L^{\frac{d}{2},\infty}(\mathbb{R}^d)$.
\end{itemize}

There holds
\begin{itemize}
\item[$(i)$]  Let $1<r, r_1, r_2<\infty$ and $1\leq \rho, \rho_1, \rho_2 \leq \infty$ be such that
\[\frac{1}{r}=\frac{1}{r_1}+\frac{1}{r_2}, \quad \frac{1}{\rho} \leq \frac{1}{\rho_1}+\frac{1}{\rho_2}.
		\]
Then for any $f \in L^{r_1, \rho_1}(\mathbb{R}^d)$ and $g\in L^{r_2, \rho_2}(\mathbb{R}^d)$
\[\|fg\|_{L^{r,\rho}} \lesssim \|f\|_{L^{r_1, \rho_1}} \|g\|_{L^{r_2,\rho_2}}.\]
\item[$(ii)$] Let  $1<r_1,r_2<\infty $ and  $1\le \rho_1,\rho_2\le \infty $  be such that 
\begin{equation*}
1=\frac{1}{r_1}+\frac{1}{r_2},\quad 1\le \frac{1}{\rho_1}+\frac{1}{\rho_2}.
\end{equation*}
Then  for any $f \in L^{r_1, \rho_1}(\mathbb{R}^d)$ and $g\in L^{r_2, \rho_2}(\mathbb{R}^d)$
\begin{equation*}
\|fg\|_{L^1}\lesssim  \|f\|_{L^{r_1, \rho_1}} \|g\|_{L^{r_2,\rho_2}}.
\end{equation*}
\end{itemize}

\label{CZ}
Let  $1<p_0<p<p_1<\infty $,  $r>0$ and $0<\theta<1$ satisfy  $\frac{1}{p}=\frac{1-\theta}{p_0}+\frac{\theta}{p_1}$. For every  $f\in L^{p_0,\infty }(\mathbb{R}^d)\cap L^{p_1,\infty }(\mathbb{R}^d)$, we have
	\begin{equation*}
		\|f\|_{L^{p,r}(\mathbb{R} ^d)}\lesssim  \|f\|_{L^{p_0,\infty }(\mathbb{R} ^d)}^{1-\theta} \|f\|_{L^{p_1,\infty }(\mathbb{R} ^d)}^{\theta}.
	\end{equation*}

\label{P:SZ} We have
\begin{itemize}
\item[$(i)$] Let $(q,r)$ be an admissible pair, then for any $f\in L^2(\mathbb{R}^d)$
\begin{align}  
\|e^{it\Delta }f\|_{L^q_t L^{r,2}_x(\mathbb{R}\times \mathbb{R}^d)} \lesssim \|f\|_{L^2_x(\mathbb{R}^d)}.\notag
\end{align}

\item[$(ii)$] Let $(q_1, r_1), (q_2,r_2)$ be two admissible pairs,  and $I\subset \mathbb{R}$ be an interval containing $t_0$. Then for any $F\in L_t^{q_2'}L^{r_2',2}_x(I\times \mathbb{R}^d)$ 
\begin{align} 
\left\|\int_{t_0}^t e^{i(t-\tau)\Delta } F(\tau) d\tau\right\|_{L^{q_1}_tL^{r_1,2}_x(I\times \mathbb{R}^d)} \lesssim \|F\|_{L^{q_2'}_tL^{r_2',2}_x(I\times \mathbb{R}^d)}.\notag
\end{align}
\end{itemize}

\label{att}
There exist parameters $\lambda_{0} > 0, \gamma_0\in[0,2\pi], \xi_0\in\mathbb{R}^d$ and $x_0\in\mathbb{R}^d$ such that
    \begin{align*}
       \delta\big(u(t)\big)
&=\left\|  e^{i \gamma_0}e^{ix\cdot\xi_0} \lambda_0^{d/2}  u \big(t, \lambda_0 (x+x_0) \big) - Q (x)  \right\|_{L_x^{2}}.
    \end{align*}

\label{conti}
    The distance function \eqref{ppp}
   is upper semicontinuous  for any $t \in I$. Moreover, it is continuous  when it is small.

\label{sequ}
    Let $u$ be a solution to \eqref{1.1} with the mass $M(u)=M(Q)$ that blows up forward in time. Let $I$ be the maximal lifespan of $u$, then there exists a sequence $t_n\to \sup I$ such that 
    \begin{equation}\label{f2.31}
        \lim_{n\to\infty}\delta\big(u(t_n)\big)=0.
    \end{equation}

\label{sequencelemma}
    Let $u$ be an almost-periodic solution with mass $M(u)=M(Q)$. Suppose $u$ blows up in both time directions and the frequency function $N(t)\leq1$ on $[0,\infty)$, then there exists a sequence of times $t_n\geq0$  and parameters $N_n>0$, $\gamma_n\in[0,2\pi]$, $\xi_n\in\mathbb{R}^d$ and $x_n\in\mathbb{R}^d$ such that
    \begin{equation}\label{sequence}
       \lim_{n\to\infty} \|e^{i\gamma_n}e^{ix\cdot\xi_n}N_n^{\frac{d}{2}}u(t_n,N_n(x-x_n))-Q\|_{L^2}=0.
    \end{equation}

\label{t2.3}
Let $0 < \eta_{\ast} \ll 1$ be a small, fixed constant to be defined later. Suppose  $u$ is a  solution to \eqref{1.1} on the maximal interval of existence $I \subset \mathbb{R}$, with $ M(u) =  M(Q)$. If $u$ blows up forward in time, and satisfies 
\begin{equation}\label{f2.32}
\sup_{t \in [0, \sup(I))}\delta\big(u(t)\big) \leq \eta_{\ast},
\end{equation}
then $u$ is either a soliton solution of the form \eqref{soliton} or a pseudo-conformal transformation of a soliton of the form \eqref{pseudosoliton}.

The proof mainly follows Dodson \cite{D2,D1}.  For the sake of completeness, we present a detailed proof here.  
Let $u(t)$ be the solution to \eqref{1.1} satisfying the assumption of Theorem \ref{main1}. Without loss of generality, we assume that $u$ blows up forward in time.  We divide into two cases: 


\textbf{Case I}. There exists some $t_{0} > 0$ such that
\begin{equation*}
\sup_{t \in [t_{0}, \sup(I))} \delta\big(u(t)\big)  \leq \eta_{\ast},
\end{equation*}
where $\eta_{\ast}$ is the small parameter in Theorem \ref{t2.3}. In this case, after translating in time so that $t_{0} = 0$, \eqref{f2.32} holds, thus we can directly  use Theorem \ref{t2.3} to prove Theorem \ref{main1}.

\textbf{Case II}.  There exists a sequence $t_{n}^{-} \nearrow \sup(I)$ such that
\begin{equation}\label{f2.35}
 \delta\big(u(t_n^-)\big)   > \eta_{\ast},
\end{equation}
for every $n$. In this case, after passing to a subsequence, we can suppose that for every $n$, $t_{n}^{-} < t_{n} < t_{n + 1}^{-}$, where $t_{n}$ is the sequence in \eqref{f2.31} and $t_{n}^{-}$ is the sequence in \eqref{f2.35}. The fact that
$\delta\big(u(t)\big)$
is upper semicontinuous as a function of $t$, and  continuous when it is small, guarantees that there exists a small, fixed $0 < \eta_{\ast} \ll 1$ such that the sequence $t_{n}^{+}$, defined by
\begin{equation*} 
t_{n}^{+} = \inf \bigg\{ t_0 \in I : \sup_{t \in [t_{0}, t_n)} \delta\big(u(t)\big) 
< \eta_{\ast}  \bigg\},
\end{equation*}
satisfies $t_{n}^{+} \nearrow \sup I$ as $n\to \infty $ and
\begin{equation}\label{f2.38}
\delta\big(u(t_n^+)\big) 
= \eta_{\ast}.
\end{equation}
Indeed, the fact that $\delta\big(u(t)\big) $ is upper semicontinuous as a function of $t$ implies that
\begin{equation*}
\bigg\{ 0 \leq t < t_{n} : \delta\big(u(t)\big)  \geq \eta_{\ast}  \bigg\}
\end{equation*}
is a closed set. Since this set is also bounded, it has a maximal element $t_{n}^{+}$, and $t_{n}^{+} \geq t_{n}^{-}$. The fact that $\delta\big(u(t)\big) $ is upper semicontinuous in time also implies that
\begin{equation}\label{edc0}
 \delta\big(u(t_n^+)\big)\geq \eta_\ast.
\end{equation}
On the other hand, since
\begin{equation}\label{edc}
\delta\big(u(t)\big) 
 < \eta_{\ast} \quad \text{for all} \quad t_{n}^{+} < t < t_{n},
\end{equation}
Lemma~\ref{conti} gives continuity near $t_n^+$ for sufficiently
small $\eta_\ast$. Letting $t\searrow t_n^+$ in \eqref{edc}, we obtain
\begin{equation}\label{f2.41}
 \delta\big(u(t_n^+)\big)   \leq \eta_{\ast}.
\end{equation}
By \eqref{edc0} and \eqref{f2.41}, we have
\begin{equation}\label{zzzx}
	\delta\big(u(t_n^+)\big) 
 = \eta_{\ast}.
\end{equation}

We then claim that 
\begin{equation}\label{scatteringnorm}
	\lim_{n \rightarrow \infty}\|u\|_{L_{t,x}^{\frac{2(d+2)}{d}}( \left[t_{n}^{+}, t_{n} \right] \times \mathbb{R}^d)} = \infty.
\end{equation}
In fact,  suppose that \eqref{scatteringnorm} fails, then, after passing to a subsequence, there exists a constant $M$ such that 
    \[
    \|u\|_{L_{t,x}^{\frac{2(d+2)}{d}}([t_{n}^{+}, t_{n}]\times \mathbb{R}^d)}\leq M \quad\text{for all}\quad n\geq0.
    \]
    By Lemma \ref{att} and Proposition \ref{sequ}, there exist parameters
$\lambda_n>0$, $\gamma_n$, $\xi_n$, and $x_n$ such that
\[
\varepsilon_{n,0}(x)
=e^{i\gamma_n}e^{ix\cdot\xi_n}\lambda_n^{d/2}
u\bigl(t_n,\lambda_n(x+x_n)\bigr)-Q(x),
\qquad
\|\varepsilon_{n,0}\|_{L_x^2}
=\delta\bigl(u(t_n)\bigr)\longrightarrow0.
\]
Set $u_n(t,x)=u(t_n+t,x)$ and define the exact solitary wave
\begin{align*}
\widetilde Q_n(t,x)
={}&\lambda_n^{-d/2}e^{-i\gamma_n}
e^{-i(x/\lambda_n-x_n)\cdot\xi_n}
e^{i(1-|\xi_n|^2)t/\lambda_n^2}\\
&\times Q\left(\frac{x}{\lambda_n}-x_n
                       +\frac{2t\xi_n}{\lambda_n^2}\right).
\end{align*}
Let $\varepsilon_n(t,x)=u_n(t,x)-\widetilde Q_n(t,x)$. Then
\[
\varepsilon_n(0,x)
=\lambda_n^{-d/2}e^{-i\gamma_n}
e^{-i(x/\lambda_n-x_n)\cdot\xi_n}
\varepsilon_{n,0}(x/\lambda_n-x_n),
\qquad
\|\varepsilon_n(0)\|_{L_x^2}=\|\varepsilon_{n,0}\|_{L_x^2},
\]
and
\[
i\partial_t\varepsilon_n+\Delta\varepsilon_n
=-F(u_n)+F(\widetilde Q_n).
\]
Since $\widetilde Q_n=u_n-\varepsilon_n$, we have
\begin{align*}
|F(u_n)-F(\widetilde Q_n)|
\lesssim{}&|\varepsilon_n|
\bigl[|x|^{-2}*|u_n|^2+|x|^{-2}*|\varepsilon_n|^2\bigr]\\
&+\bigl(|x|^{-2}*|\varepsilon_nu_n|\bigr)
\bigl(|u_n|+|\varepsilon_n|\bigr).
\end{align*}
For $J\subset[t_n^+-t_n,0]$, Strichartz estimates and the
Hardy--Littlewood--Sobolev inequality give
\begin{align}\label{reduction:perturbation}
&\|\varepsilon_n\|_{L_t^\infty L_x^2(J\times\mathbb{R}^d)}
+\|\varepsilon_n\|_{L_t^2L_x^{\frac{2d}{d-2}}(J\times\mathbb{R}^d)}\notag\\
&\quad\lesssim\inf_{t\in J}\|\varepsilon_n(t)\|_{L_x^2}
+\|\varepsilon_n\|_{L_t^6L_x^{\frac{6d}{3d-2}}(J\times\mathbb{R}^d)}^3\notag\\
&\qquad+\|u_n\|_{L_t^6L_x^{\frac{6d}{3d-2}}(J\times\mathbb{R}^d)}
\|\varepsilon_n\|_{L_t^6L_x^{\frac{6d}{3d-2}}(J\times\mathbb{R}^d)}^2\notag\\
&\qquad+\|u_n\|_{L_t^6L_x^{\frac{6d}{3d-2}}(J\times\mathbb{R}^d)}^2
\|\varepsilon_n\|_{L_t^6L_x^{\frac{6d}{3d-2}}(J\times\mathbb{R}^d)}.
\end{align}
By local theory and the assumed spacetime bound,
$\|u_n\|_{S^0([t_n^+-t_n,0])}\lesssim_M1$. Partitioning
$[t_n^+-t_n,0]$ into finitely many intervals on which
$\|u_n\|_{L_t^6L_x^{6d/(3d-2)}}$ is small, and applying
\eqref{reduction:perturbation} successively backward from $t=0$, we obtain
\[
\|\varepsilon_n\|_{L_t^\infty L_x^2([t_n^+-t_n,0]\times\mathbb{R}^d)}
\lesssim_M\|\varepsilon_n(0)\|_{L_x^2}\longrightarrow0.
\]
Since $\widetilde Q_n(t_n^+-t_n)$ lies on the ground-state orbit,
\[
\delta\bigl(u(t_n^+)\bigr)
\leq\|\varepsilon_n(t_n^+-t_n)\|_{L_x^2}\longrightarrow0,
\]
contradicting \eqref{zzzx}.

Using the fact that $u$ is a minimal-mass blowup solution, there exist $w_0\in L_x^2$ and parameters $\widehat{\lambda}_n > 0$, $\widehat{\gamma}_n\in[0,2\pi]$, $\widehat{x}_n\in\mathbb{R}^d$ and $\widehat{\xi}_n\in\mathbb{R}^d$, 
 such that
\begin{equation}\label{f2.43}
\left\|e^{i\widehat{\gamma}_{n }}e^{ix\cdot\widehat{ \xi}_n}\widehat{\lambda}_n^{d/2}  u \left(t_{n}^{+}, \widehat{\lambda}_n
\left(x+ \widehat{x}_n \right) \right)-w_{0} (x) \right\|^2_{L^2_x} \rightarrow 0, \text{ as } n \to \infty .
\end{equation}
Moreover,   $ \| w_0 \|_{L_x^{2}} = \| Q\|_{L_x^{2}}$, and by \eqref{f2.38},
\begin{equation}\label{f2.44}
\inf_{\substack{\lambda>0, \gamma\in [0,2\pi]\\\tilde{x},\xi\in \mathbb{R}^d}}
\left\|  e^{i \gamma}e^{ix\cdot\xi} \lambda^{d/2}  w_0 \left(\lambda  \left(x+\tilde{x} \right) \right) - Q (x)  \right\|_{L_x^{2}} =\eta_{\ast}.
\end{equation}
Let $w$ be the solution to \eqref{1.1} with initial data $w_{0}$. Then the fact that $u$ blows up forward in time and $t_n^+\nearrow \sup I$ as $n \to \infty$ implies that $w$ blows up both forward and backward in time. Denote the maximal interval of existence of $w$ as $\tilde{I}$. We claim that
\begin{equation}\label{f2.45}
\delta\big(w(t)\big)\leq \eta_{\ast} ,\quad \forall \,  t\in [0, \sup\tilde{I}).
\end{equation}
Indeed, for any compact interval $[0, M]\subseteq  \tilde{I}$, \eqref{f2.43} and the stability lemma guarantee that as $n \to \infty$, 
\begin{align}\label{ijz}
\|u'_n(t)-w(t) \|_{L_t^{\infty} L_x^2\cap L_{t, x}^{\frac{2(d+2)}{d}}  ([0,M]\times\mathbb{R}^d)}\to 0,
\end{align}
where
\[
\begin{aligned}
u'_n(t,x)={}&e^{i\widehat\gamma_n}
e^{ix\cdot\widehat\xi_n-it|\widehat\xi_n|^2}
\widehat\lambda_n^{d/2}\\
&\times u\left(t_n^++\widehat\lambda_n^2t,
\widehat\lambda_n(x+\widehat x_n-2t\widehat\xi_n)\right).
\end{aligned}
\]
Clearly, \eqref{scatteringnorm}, \eqref{f2.43}, \eqref{ijz}, and the arbitrariness in the choice of $M$ 
imply that \eqref{f2.45} holds.

However, Theorem \ref{t2.3}, \eqref{f2.44}, and \eqref{f2.45} imply that $w$ must be of the form \eqref{pseudosoliton}. Such a solution scatters backward in time, which contradicts the fact that $w$ blows up both forward and backward in time. Thus \eqref{f2.35} cannot happen, which precludes possibility of Case II. So we finish the proof.

Let $1\leqslant p<\infty$. We define $U_\Delta^p(\mathbb{R})$ as an atomic space with atoms $v^\lambda(t,x)$ given by 
\begin{align*}
v^\lambda(t,x)=\sum_{k=0}^{M}\chi_{[t_k,t_{k+1})}(t)e^{it\Delta} v_k^\lambda(x),\quad
\sum_{k=0}^M\left\| v_k^\lambda \right\|_{L^2(\mathbb{R}^d)}^p=1.
\end{align*}
In the summation above, $M$ can be finite or infinite. If $M$ is finite, we further assume $t_0=-\infty$ and $t_{M+1}=+\infty$. The norm of $U_\Delta^p (\mathbb{R})$ is defined as 
\begin{align*}
\| v \|_{U_\Delta^p(\mathbb{R})}
= \inf\left\{\sum_{\lambda\in\mathbb{Z}} |c_\lambda|: v =\sum_{\lambda\in\mathbb{Z}}c_\lambda v^\lambda, \hspace{1ex} v^\lambda\mbox{ is an atom}\right\},
\end{align*}
where the infimum is taken over all atom decompositions. 
For any interval $I\subseteq\mathbb{R}$, we can define the local version as
\begin{align*}
\| v\|_{U_\Delta^p \left(I \right)}=\| v \chi_I(t)\|_{U_\Delta^p \left(\mathbb{R}\right)},
\end{align*}
where $\chi_I$ denotes the characteristic function of the set $I$.

Let $1\leqslant p<\infty$. We define $V_\Delta^p(\mathbb{R} )$ as the space of right-continuous functions $v \in L_t^{\infty} L_x^2(\mathbb{R}\times\mathbb{R}^d)$ endowed with the norm
\begin{align*}
\| v \|_{V_\Delta^p \left(\mathbb{R}\right)}^p
= \| v \|_{L_t^\infty L_x^2(\mathbb{R}\times\mathbb{R}^d)}^p + \sup_{\{t_k\}\nearrow\infty}
\sum_{k} \big\|e^{-it_{k+1}\Delta} v(t_{k+1})-e^{- it_k\Delta} v(t_k)\big\|_{L^2(\mathbb{R}^d)}^p.
\end{align*}
For any interval $I\subseteq\mathbb{R}$, we can define the local version as
\begin{align*}
\| v \|_{V_\Delta^p \left(I \right)}=\| v \chi_I(t)\|_{V_\Delta^p \left(\mathbb{R}\right)}.
\end{align*}

\label{property}
Suppose $1<p<q<\infty$ and $t_0\leqslant t_1\leqslant t_2$. For $I\subset \mathbb{R}$, we have
\begin{align}
(i)&\; U_\Delta^p \left(I \right)\subseteq V_\Delta^p \left(I \right)\subseteq U_\Delta^q \left(I \right),\label{embeddingvp} \\
(ii)&\;\| v \|_{U_\Delta^p \left([t_0,t_1] \right)}\leqslant\| v \|_{U_\Delta^p \left([t_0,t_2] \right)},  \notag \\
(iii)&\;\| v \|_{U_\Delta^2 \left([t_0,t_2] \right)}^2\leqslant\| v \|_{U_\Delta^2 \left([t_0,t_1] \right)}^2
+\| v \|_{U_\Delta^2 \left([t_1,t_2]\right)}^2,  \notag\\
(iv)&\;\| v \|_{L_t^p L_x^q \left(I\times\mathbb{R}^d \right)}\lesssim_p \| v \|_{U_\Delta^p \left(I \right)},\;(p,q)\in\Lambda_0 \label{u-pstrichartz}\\
(v)&\; \| v \|_{U_\Delta^2 \left(I \right)}\lesssim_p \inf_{\tilde{t}\in I} \left\| v(\tilde{t}) \right\|_{L^2(\mathbb{R}^d)}
+\|i\partial_t v +\Delta v \|_{L_t^{p'} L_x^{q'} \left(I\times\mathbb{R}^d \right)},\;(p,q)\in\Lambda_0. \label{dupstrichartz}
\end{align}

\label{up-dual}
Let $p>1$ and let $I$ be an interval with $t_0\in I$, we have
\begin{align*}
\left\|\int_{t_0}^t e^{i(t-\tau)\Delta} F(\tau) \, {d} \tau\right\|_{U_\Delta^p \left(I\right)}
\lesssim_p \sup_{\| G \|_{V_\Delta^{p'} \left(I \right)}\leq1} \Big|\int_I\int_{\mathbb{R}^d}F\bar{G}\;dx\;dt\Big|.	
\end{align*}

\label{atominterpolation}
For any $0<\delta<1$,  we have
 \begin{align}\nonumber
   & \Big \|\int_{a}^te^{i(t-s)\Delta}F(s)\; ds\Big\|_{U_{\Delta}^2([a,b])}\\ \label{rrrt}  \lesssim_{\delta}&\|F\|^{\delta}_{L_t^{1}L_{x}^{2}}\bigg\{\sup_{\|v\|_{U_{\Delta}^2([a,b])}\leq 1}\Big|\int_a^b\int_{\mathbb{R}^d}F\bar{v}\;dx\;dt\Big|\bigg\}^{1-\delta}.
 \end{align}

\label{longtime}
Let $u$ be the  solution as in Theorem \ref{t2.3}. Let $J = [a,b]$ be an interval for which
$\lambda(t)\geq1$ and
\begin{equation}\label{f5.7}
    \begin{cases}
     \int_{a}^b \lambda(t)^{-2} \, {d} t = T=2^{3k_0},\;   \int_{a}^b\frac{1}{\lambda(t)^2}\|\epsilon(t)\|_{L_x^2}^2\, {d} t\leq \eta_1,\\
     \sup\limits_{t \in J}\frac{|\xi(t)|}{\lambda(t)}\leq \eta_0,\ \sup\limits_{t\in J}|x(t)|\leq T^{\frac{1}{25}},
    \end{cases}
\end{equation}
for some $\eta_0,\eta_1\ll1$. Then the long-time Strichartz estimate,
\begin{align}\label{f5.66}
\|P_{\geq k_0}u\|_{U_{\Delta}^2([a,b])}\lesssim \Big(\frac{1}{T}\int_{a}^{b}\frac{1}{\lambda(t)^2}\|\epsilon(t)\|^2_{L_x^2}\, dt\Big)^{1/2}+\frac{1}{T^{10}},
\end{align}
holds (universally) for sufficiently small $\eta_{\ast}\ll1$ and large $T\gg1$ and the implicit constant is independent of $T$.

\label{integ1} Under the assumptions of Theorem \ref{longtime}, for any $i\geq [\frac{\log_2(T)}{4}]+5$ and $0<\delta<1$, we have
\begin{align}\label{finalzz}
 &\|P_{\geq i}u\|_{U_{\Delta}^2([a,b])}\notag\\
 \lesssim_{\delta}& \inf_{t\in[a,b]}\|\epsilon(t)\|_{L_x^2(\mathbb{R}^d)}
+\frac{1}{T^{20}} \\\nonumber&+\big[{\eta_1^{\frac{1}{2}-}}+\eta_1^{1-}+(T^{\frac{d}{d+2}\delta}+T^{\frac{d+4}{2(d+2)}\delta})(2^{-i}T^{1/25})^{1-\delta}\big]\|P_{\geq i-4}u\|_{U_{\Delta}^2\left([a,b]\right)}
\end{align}
for sufficiently large $T.$

We observe that by the standard local theory,
    \begin{equation}\label{equ:uU2est}
        \|u\|_{U_{\Delta}^2([a,b])}\lesssim T^{\frac12}.
    \end{equation}
By \eqref{f5.7} and integral mean value theorem, we get
$$\inf_{t\in[a,b]}\|\epsilon(t)\|_{L_x^2(\mathbb{R}^d)}
\lesssim \Big(\frac{1}{T}\int_{a}^{b}\frac{1}{\lambda(t)^2}\|\epsilon(t)\|^2_{L_x^2}\, dt\Big)^{1/2}.$$
Hence, using  Lemma \ref{integ1}, we obtain
\begin{align*}
   \|P_{\geq[\frac{\log_2(T)}{4}]+5}u\|_{U_{\Delta}^2([a,b])}\lesssim_{\delta}& \Big(\frac{1}{T}\int_{a}^{b}\frac{1}{\lambda(t)^2}\|\epsilon(t)\|^2_{L_x^2}\, dt\Big)^{1/2}+\frac{1}{T^{20}}
   \\&+\big({\eta_1^{1-}}+\eta_1^{\frac{1}{2}-}+T^{\frac{d}{d+2}\delta-\frac{21(1-\delta)}{100}}+T^{\frac{d+4}{2(d+2)}\delta-\frac{21(1-\delta)}{100}}\big)T^{\frac12}.
   \end{align*}
Letting $A:=C_\delta({\eta_1^{1-}}+\eta_1^{\frac{1}{2}-}+T^{\frac{d}{d+2}\delta-\frac{21(1-\delta)}{100}}+T^{\frac{d+4}{2(d+2)}\delta-\frac{21(1-\delta)}{100}})$, with $C_\delta$ large enough to include the constant in Lemma~\ref{integ1}, we can iterate $j-1$ times to show that
\[
   \|P_{\geq[\frac{\log_2(T)}{4}]+1+4j}u\|_{U_{\Delta}^2([a,b])}\lesssim_{\delta} 
   A^{j}T^{\frac12}+
 \Big[\Big(\frac{1}{T}\int_{a}^{b}\frac{1}{\lambda(t)^2}\|\epsilon(t)\|^2_{L_x^2}\, dt\Big)^{1/2}
 +\frac1{T^{20}}\Big]  \sum_{k=0}^jA^k.
\]
Choose $\delta>0$ sufficiently small, then $\eta_1$ sufficiently
small and $T$ sufficiently large so that $A\ll1$. Taking
$j\sim\log_2(T)/48$ with $\lfloor\log_2(T)/4\rfloor+1+4j\leq k_0$,
we have $A^j\leq T^{-22}$, provided $A$ is sufficiently small.
Thus
\begin{align}\label{zzbvz}
\|P_{\geq k_0}u\|_{U_\Delta^2([a,b])}
\lesssim{}&
\left(\frac1T\int_a^b\lambda(t)^{-2}
\|\epsilon(t)\|_{L_x^2}^2\,dt\right)^{1/2}
+T^{-20}+A^jT^{1/2}.
\end{align}
Since $A^j\leq T^{-22}$, the last term is bounded by $T^{-20}$,
which together with \eqref{zzbvz} yields
\[
\|P_{\geq\frac{\log_2(T)}{3}}u\|_{U_{\Delta}^2([a,b])}\lesssim \Big(\frac{1}{T}\int_{a}^{b}\frac{1}{\lambda(t)^2}\|\epsilon(t)\|^2_{L_x^2}\, dt\Big)^{1/2}+\frac{1}{T^{10}},
\]
as desired.

For the sake of brevity, we will omit the integration domain in each formula from this point onward, except for the first line.
By Duhamel's formula and Strichartz estimate, we have for any $t_0\in [a,b]$
\[
\|P_{\geq i}u\|_{U^2_{\Delta}([a,b])}\lesssim \|P_{\geq i} u(t_0)\|_{L_x^2}+\Big\|\int_{t_0}^te^{i(t-s)\Delta} P_{\geq i}[(|x|^{-2}*|u|^2)u]\ ds\Big\|_{U^2_{\Delta}([a,b])}.
\]
From now on we stipulate that if $(p,q)\in\Lambda_0$, then the chosen $(p_{\pm}, q_{\mp})$ also belongs to $\Lambda_0$. In view of  \eqref{dupstrichartz} and \eqref{rrrt}, for any $t_0$, we obtain
\begin{align}\notag
&\|P_{\geq i}u\|_{U^2_{\Delta}([a,b])}\\\label{equ:lintermpu}
\lesssim& \|P_{\geq i} u(t_0)\|_{L_x^2}\\\label{equ:inhterm1}
&+\Big\|\int_{t_0}^te^{i(t-s)\Delta}P_{\geq i}\big[(|x|^{-2}*|u|^2)P_{\geq i-4}u\big]\ ds\Big\|_{U^2_{\Delta}([a,b])}\\\label{equ:inhterm2}
&+\Big\|\int_{t_0}^te^{i(t-s)\Delta}P_{\geq i}\Big(\big[|x|^{-2}*\text{\O}(\bar{u}P_{\geq i-4}u)\big]P_{\leq i-4}u\Big)\ ds\Big\|_{U^2_{\Delta}([a,b])}
\end{align}
where the expression $\text{\O}(X)$ denotes a finite linear combination of terms
 that resemble $X$ up to  complex conjugation.

{\bf The estimate of \eqref{equ:lintermpu}:} Using the fact that $\lambda(t)\geq 1$, Proposition \ref{grondstate2} and Bernstein's inequality, we see that
 \begin{align}\label{vvv1}
\|P_{\geq i} u(t_0)\|_{L_x^2}&\leq \|\epsilon(t_0)\|_{L_x^2}+\|P_{\geq i}\tilde{Q}\|_{L^2}\notag\\
     &\leq \|\epsilon(t_0)\|_{L_x^2}+\|P_{\geq i-1} Q\|_{L^2}\notag\\
     &\leq  \|\epsilon(t_0)\|_{L_x^2}+\frac{1}{2^{1000i}}\||\nabla|^{1000}Q\|_{L^{2}}\notag\\
&\leq\|\epsilon(t_0)\|_{L_x^2}+\frac{1}{T^{20}},
 \end{align}
 which is acceptable.


{\bf The estimate of \eqref{equ:inhterm1}:} By \eqref{decomp}, we have
\begin{align}\notag
    u(t,x)=&e^{-i\gamma(t)}e^{-i\frac{x-x(t)}{\lambda(t)}\cdot\xi(t)}\lambda(t)^{-\frac{d}{2}}
    \Big(\epsilon\big(t,\tfrac{x-x(t)}{\lambda(t)}\big)+Q\big( \tfrac{x-x(t)}{\lambda(t)}\big)\Big)\\\label{equ:uepsQ}
    \triangleq&\tilde{\epsilon}(t,x)+\tilde{Q}(t,x).
\end{align}
This together with Strichartz estimate and Lemma \ref{atominterpolation} implies
\begin{align}\notag
\eqref{equ:inhterm1}\lesssim&\Big\|\int_{t_0}^te^{i(t-s)\Delta}P_{\geq i}\big[(|x|^{-2}*|\tilde{\epsilon}|^2)P_{\geq i-4}u\big]\ ds\Big\|_{U^2_{\Delta}}\\\notag
&+\Big\|\int_{t_0}^te^{i(t-s)\Delta}P_{\geq i}\big[(|x|^{-2}*|\tilde{Q}|^2)P_{\geq i-4}u\big]\ ds\Big\|_{U^2_{\Delta}}\\\label{equ:x-2epsest}
\lesssim&\|(|x|^{-2}*|\tilde{\epsilon}|^2)P_{\geq i-4}u\|_{L_t^{1}L_x^{2}}\\\notag
&+\|(|x|^{-2}*|\tilde{Q}|^2)P_{\geq i-4}u\|^{\delta}_{L_t^{1}L_x^{2}}\notag\\
&\qquad\times\sup_{\|v\|_{U_{\Delta}^{2}}\leq 1}\|(|x|^{-2}*|\tilde{Q}|^2)P_{\geq i-4}uP_{\geq i}v\|^{1-\delta}_{L_{t,x}^{1}}.
\end{align}

Next, using \eqref{reduction:perturbation} and the assumption
\eqref{f5.7}, we prove that
\begin{equation}\label{equ:tildeespest}
    \|\tilde{\epsilon}\|_{L_t^2L_x^{\frac{2d}{d-2}}([a,b]\times\mathbb{R}^d)}\lesssim \Big(\int_{a}^b\frac{1}{\lambda(t)^2}\|\epsilon(t)\|_{L_x^2}^2\, dt\Big)^\frac12\lesssim \eta_1^\frac12.
\end{equation}
In fact, we can divide the interval $[a,b]$ into the subintervals $J_l$ satisfying
\[
\int_{J_l}\frac{1}{\lambda(t)^2}\,dt=1\quad\text{for all}\quad 0\leq l\leq 2^{3k_0}-1.
\]
By \eqref{f4.45} and \eqref{f4.56},
\[
\sup_{t\in J_i}\lambda(t)\sim\inf_{t\in J_i}\lambda(t),\qquad
\sup_{t\in J_i}\|\epsilon(t)\|_{L_x^2}
\sim\inf_{t\in J_i}\|\epsilon(t)\|_{L_x^2}.
\]
Moreover,
 $\tilde{Q}$ satisfies the equation 
\[
i\partial_t \tilde{Q}+\Delta\tilde{Q}=-(|x|^{-2}\ast|\tilde{Q}|^2)\tilde{Q}+\mathcal{G}
\]
where the term $\mathcal{G}$ is given by
\[
\begin{aligned}
\mathcal{G}={}&\lambda^{-d/2}e^{-i\gamma-i\varphi}\\
&\quad\times\Bigg\{\left(\gamma_t-\frac{x_t\cdot\xi}{\lambda}
+y\cdot\Big(\xi_t-\xi\frac{\lambda_t}{\lambda}\Big)
+\frac{1-|\xi|^2}{\lambda^2}\right)Q(y)\\
&\qquad+i\left(-\frac d2\frac{\lambda_t}{\lambda}Q(y)
-\frac{x_t}{\lambda}\cdot\nabla Q(y)
-\frac{\lambda_t}{\lambda}y\cdot\nabla Q(y)
-2\frac{\xi\cdot\nabla Q(y)}{\lambda^2}\right)\Bigg\}.
\end{aligned}
\]
with
\[
y = \frac{x - x(t)}{\lambda(t)}, \qquad \varphi = y\cdot\xi(t).
\]
Applying Lemma~\ref{P:SZ} to the equation for $\widetilde\epsilon$
and estimating the nonlinear terms as in \eqref{reduction:perturbation},
we use \eqref{f4.45}, \eqref{f4.53}--\eqref{f4.55} to obtain
   \[
   \Big\|\frac{1}{\lambda(t)^{d/2}}\epsilon \Big(t,\frac{x-x(t)}{\lambda(t)}\Big)\Big\|^2_{L_t^2L_x^{\frac{2d}{d-2},2}(J_i\times\mathbb{R}^d)}\lesssim \inf_{t\in J_i} \|\epsilon(t)\|_{L_x^{2}}^2\lesssim \int_{J_i}\frac{1}{\lambda(t)^2}\|\epsilon(t)\|^2_{L_x^2}\, dt.
   \]
Summing over $i$, we readily obtain
\begin{equation}\label{estepsilonnorm}
   \Big\|\frac{1}{\lambda(t)^{d/2}}\epsilon\Big(t,\frac{x-x(t)}{\lambda(t)}\Big)\Big\|^2_{L_t^2L_x^{\frac{2d}{d-2},2}([a,b]\times\mathbb{R}^d)}\lesssim  \int_{a}^b\frac{1}{\lambda(t)^2}\|\epsilon(t)\|^2_{L_x^2}\, dt\leq\eta_1,
\end{equation}
as desired. Hence
\begin{align*}
    \|(|x|^{-2}*|\tilde{\epsilon}|^2)P_{\geq i-4}u\|_{L_t^{1}L_x^{2}}\lesssim \|\tilde{\epsilon}\|^2_{L_t^{2+}L_x^{\frac{2d}{d-2}-}} \|P_{\geq i-4}u\|_{L_t^{\infty-}L_x^{2+}}
    \lesssim \eta_1^{1-}\|P_{\geq i-4}u\|_{U^2_\Delta}.
\end{align*}
Plugging it into \eqref{equ:x-2epsest}  yields
\begin{align}\notag
\eqref{equ:inhterm1}\lesssim&\eta_1^{1-}\|P_{\geq i-4}u\|_{U^2_\Delta}\\\notag
&+\|(|x|^{-2}*|\tilde{Q}|^2)P_{\geq i-4}u\|^{\delta}_{L_t^{1}L_x^{2}}\notag\\
&\qquad\times\sup_{\|v\|_{U_{\Delta}^{2}}\leq 1}\big\|(|x|^{-2}*|\tilde{Q}|^2)P_{\geq i-4}uP_{\geq i}v\big\|^{1-\delta}_{L_{t,x}^{1}}.
\end{align}


{\bf The estimate of \eqref{equ:inhterm2}:} By the decomposition \eqref{equ:uepsQ}, Strichartz estimate and Lemma \ref{atominterpolation}, we have
\begin{align}\notag
\eqref{equ:inhterm2}\lesssim&
\Big\|\int_{t_0}^te^{i(t-s)\Delta}P_{\geq i}\Big(\big[|x|^{-2}*\text{\O}(\tilde{\epsilon}\overline{P_{\geq i-4}u})\big]P_{\leq i-4}\tilde{\epsilon}\Big)\ ds\Big\|_{U^2_{\Delta}}\\\notag
&+\Big\|\int_{t_0}^te^{i(t-s)\Delta}P_{\geq i}\Big(\big[|x|^{-2}*\text{\O}(\tilde{Q}\overline{P_{\geq i-4}u})\big]P_{\leq i-4}\tilde{\epsilon}\Big)\ ds\Big\|_{U^2_{\Delta}}\\\notag
&+\Big\|\int_{t_0}^te^{i(t-s)\Delta}P_{\geq i}\Big(\big[|x|^{-2}*\text{\O}(\tilde{\epsilon}\overline{P_{\geq i-4}{u}})\big]P_{\leq i-4}\tilde{Q}\Big)\ ds\Big\|_{U^2_{\Delta}}\\\notag
&+\Big\|\int_{t_0}^te^{i(t-s)\Delta}P_{\geq i}\Big(\big[|x|^{-2}*\text{\O}(\tilde{Q}\overline{P_{\geq i-4}u})\big]P_{\leq i-4}\tilde{Q}\Big)\ ds\Big\|_{U^2_{\Delta}}\\\notag
\lesssim&\big\|(|x|^{-2}*|\tilde{\epsilon}P_{\geq i-4}u|)\tilde{\epsilon}\big\|_{L_t^{1}L_x^{2}}\notag\\
&+\big\|(|x|^{-2}*|\tilde{Q}P_{\geq i-4}u|)\tilde{\epsilon}\big\|_{L_t^{1}L_x^{2}}+\|(|x|^{-2}*|\tilde{\epsilon}P_{\geq i-4}u|)\tilde{Q}\|_{L_t^{1}L_x^{2}}\notag\\
&+\big\|(|x|^{-2}*|P_{\geq i-4}u\tilde Q|)\tilde Q\big\|^{\delta}_{L_t^{1}L_x^{2}}\notag\\
&\qquad\times\sup_{\|v\|_{U_{\Delta}^{2}}\leq 1}\big\|\big(|x|^{-2}*\text{\O}(\tilde{Q}\overline{P_{\geq i-4}u})\big)P_{\leq i-4}\tilde{Q}P_{\geq i}v\big\|^{1-\delta}_{L_{t,x}^1}\notag\\\notag
\lesssim&\big\|\tilde{\epsilon}(t)\big\|_{L_t^{2+}L_x^{\frac{2d}{d-2}-}}\|\tilde{\epsilon}(t)\|_{L_t^{\infty-}L_x^{2+}}\|P_{\geq i-4}u\|_{L_t^{2+}L_x^{\frac{2d}{d-2}-}}\\\notag
&+\|\tilde{\epsilon}\|_{L_t^{2}L_x^{\frac{2d}{d-2},2}}\|\tilde{Q}\|_{L_t^{\infty}L_x^{2}}\|P_{\geq i-4}u\|_{L_t^{2}L_x^{\frac{2d}{d-2},2}}\\\notag
&+\|(|x|^{-2}*|P_{\geq i-4}u\tilde{Q}|)\tilde{Q}\|^{\delta}_{L_t^{1}L_x^{2}}\notag\\
&\qquad\times\sup_{\|v\|_{U_{\Delta}^{2}}\leq 1}\big\|\big(|x|^{-2}*\text{\O}(\tilde{Q}\overline{P_{\geq i-4}u})\big)P_{\leq i-4}\tilde{Q}P_{\geq i}v\big\|^{1-\delta}_{L_{t,x}^1}\\\notag
\lesssim&\eta_1^{\frac12-}\|P_{\geq i-4}u\|_{U^2_\Delta}\\\notag
&+\|(|x|^{-2}*|P_{\geq i-4}u\tilde{Q}|)\tilde{Q}\|^{\delta}_{L_t^{1}L_x^{2}}\notag\\
&\qquad\times\sup_{\|v\|_{U_{\Delta}^{2}}\leq 1}\big\|\big(|x|^{-2}*\text{\O}(\tilde{Q}\overline{P_{\geq i-4}u})\big)P_{\leq i-4}\tilde{Q}P_{\geq i}v\big\|^{1-\delta}_{L_{t,x}^1}.
\end{align}

Plugging the above estimates into \eqref{equ:lintermpu}-\eqref{equ:inhterm2}, and
observing that the implicit constant is independent of $t_0\in[a,b]$, we obtain that
\begin{align}
    &\|P_{\geq i}u\|_{U^2_{\Delta}([a,b])}\lesssim \inf_{t\in [a,b]}\|\epsilon(t)\|_{L_x^2}+\frac{1}{T^{20}}+\big[\eta_1^{\frac{1}{2}-}+\eta_1^{1-}\big]\|P_{\geq i-4}u\|_{U^2_{\Delta}}\notag\\
&+\big\|(|x|^{-2}*|\tilde{Q}|^2)P_{\geq i-4}u\big\|^{\delta}_{L_t^{1}L_x^{2}}\notag\\
&\qquad\times\sup_{\|v\|_{U_{\Delta}^{2}}\leq 1}\big\|(|x|^{-2}*|\tilde{Q}|^2)P_{\geq i-4}uP_{\geq i}v\big\|^{1-\delta}_{L_{t,x}^{1}}\notag\\
&+\big\|(|x|^{-2}*|P_{\geq i-4}u\tilde{Q}|)\tilde{Q}\big\|^{\delta}_{L_t^{1}L_x^{2}}\notag\\
&\qquad\times\sup_{\|v\|_{U_{\Delta}^{2}}\leq 1}\big\|\big(|x|^{-2}*\text{\O}(\tilde{Q}\overline{P_{\geq i-4}u})\big)P_{\leq i-4}\tilde{Q}P_{\geq i}v\big\|^{1-\delta}_{L_{t,x}^1}.\label{cbz}
\end{align}











By H\"older's inequality and Hardy-Littlewood-Sobolev's inequality and the fact that $\lambda(t)\geq1$,
\begin{align}\label{mmty}
 &\|(|x|^{-2}*|\tilde{Q}|^2)P_{\geq i-4}u\|_{L_t^{1}L_x^{2}}+\|(|x|^{-2}*|P_{\geq i-4}u\tilde{Q}|)\tilde{Q}\|_{L_t^{1}L_x^{2}}\notag\\
\lesssim& \|\tilde{Q}\|^2_{L_{t,x}^{\frac{2(d+2)}{d}}}\|P_{\geq i-4}u\|_{L_t^{\frac{d+2}{2}}L_x^{\frac{2d(d+2)}{(d+4)(d-2)}}}\notag\\
&+\|\tilde{Q}\|_{L_{t,x}^{\frac{2(d+2)}{d}}}\|P_{\geq i-4}u\|_{L_{t,x}^{\frac{2(d+2)}{d}}}\|\tilde{Q}\|_{L_t^{\frac{d+2}{2}}L_x^{\frac{2d(d+2)}{(d+4)(d-2)}}}\notag\\
\lesssim& \Big(\int_{a}^b \frac{1}{\lambda(t)^2}\, dt\Big)^{\frac{d}{(d+2)}}\|P_{\geq i-4}u\|_{U_{\Delta}^2}+\Big(\int_{a}^b \frac{1}{\lambda(t)^2}\, dt\Big)^{\frac{d}{2(d+2)}+\frac{2}{d+2}}\|P_{\geq i-4}u\|_{U_{\Delta}^2}\notag\\
\lesssim& \big[T^{\frac{d}{(d+2)}}+T^{\frac{d+4}{2(d+2)}}\big]\|P_{\geq i-4}u\|_{U_{\Delta}^2}.
\end{align}

Thus, it remains to estimate 
\begin{equation}\label{equ:pi-4up-2v}
    \sup_{\|v\|_{U_{\Delta}^{2}}\leq 1}\big\|(|x|^{-2}*|\tilde{Q}|^2)P_{\geq i-4}uP_{\geq i}v\big\|_{L_{t,x}^{1}},
\end{equation}
 and
\begin{equation}\label{equ:pi-4Qpi-2v}
\sup_{\|v\|_{U_{\Delta}^{2}}\leq 1}\big\|\big(|x|^{-2}*\text{\O}(\tilde{Q}\overline{P_{\geq i-4}u})\big)P_{\leq i-4}\tilde{Q}P_{\geq i}v\big\|_{L_{t,x}^1}.
\end{equation}
For this, we will use \emph{local smoothing estimate}, which, however, relies on the smoothness of $Q$. We observe that by local smoothing estimate (see e.g. \cite{CS88}), for any $R>0$, $i\geq 1$ and $v_0\in L^2$,
\[
\|e^{it\Delta}P_{\geq i}v_0\|_{L_{t,x}^2(\mathbb{R}\times B_{R}(0))}\lesssim R^{1/2}2^{-i/2}\|v_0\|_{L_x^2}.
\]
Therefore, for any atomic decomposition $v=\sum_{\lambda\in\mathbb{Z}}c_\lambda  v^\lambda$, 
\begin{align}
\left\|P_{\geq i} v\right\|_{L_{t,x}^2 \left([a,b]\times B_{R}(0) \right)}
&\lesssim \sup_{\lambda\in\mathbb{Z}} \left\|P_{\geq i}v^{\lambda} \right\|_{L_{t,x}^2(\mathbb{R}\times B_{R}(0))}\cdot \sum_{\lambda\in\mathbb{Z}}|c_{\lambda}|\notag\\
&\lesssim R^{1/2}2^{-i/2}\sum_{\lambda\in\mathbb{Z}}|c_{\lambda}|,
\end{align}
and so
\begin{equation}\label{f5.20}
    \left\|P_{\geq i} v\right\|_{L_{t,x}^2 \left([a,b]\times B_{R}(0) \right)}\lesssim R^{1/2}2^{-i/2}\|P_{\geq i}v\|_{U_{\Delta}^2([a,b])}.
\end{equation}

{\bf The estimate of \eqref{equ:pi-4up-2v}:}
Now we set   $\Omega_j=B_{2^{j}}(0)\setminus B_{2^{j-1}}(0), \ j\in \mathbb{Z}$, then by H\"older's inequality, assumption \eqref{f5.7}, and the local smoothing estimate \eqref{f5.20}, 
we obtain
\begin{align}\label{f5.21}
&\sup_{\left\|v\right\|_{U_{\Delta}^{2}\left([a,b]\right)}\leq 1}
\left\|[(|x|^{-2}*|\tilde{Q}|^2)P_{\geq i-4}u]P_{\geq i}v \right\|_{L_{t,x}^1 \left([a,b]\times \mathbb{R}^d \right)}\notag\\
&\leq\sup_{\left\|v\right\|_{U_{\Delta}^{2}\left([a,b]\right)}\leq 1}
\sum_{j=-\infty}^{\infty}\left\|(|x|^{-2}*|\tilde{Q}|^2)P_{\geq i-4}uP_{\geq i}v \right\|_{L_{t,x}^1 \left([a,b]\times \Omega_j\right)}\notag\\
&\lesssim \sum_{j=-\infty}^\infty2^{j/2}2^{-i/2}\left\|(|x|^{-2}*|\tilde{Q}|^2)P_{\geq i-4}u\right\|_{L_{t,x}^2 \left([a,b]\times \Omega_j\right)}\notag\\
&\lesssim \sum_{j=-\infty}^\infty2^{j/2}2^{-i/2}\|(|x|^{-2}*|\tilde{Q}|^2)\|_{L_{t,x}^{\infty}\left([a,b]\times \Omega_j\right)}\|P_{\geq i-4}u\|_{L_{t,x}^{2}\left([a,b]\times \Omega_j\right)}\notag\\
&\lesssim \sum_{j=-\infty}^\infty2^{j}2^{-i}\|(|x|^{-2}*|\tilde{Q}|^2)\|_{L_{t,x}^{\infty}\left([a,b]\times \Omega_j\right)}\|P_{\geq i-4}u\|_{U_{\Delta}^2\left([a,b]\right)}\notag\\
&\lesssim 2^{-i}\|P_{\geq i-4}u\|_{U_{\Delta}^2\left([a,b]\right)}\sum_{j=-\infty}^\infty2^{j}\|(|x|^{-2}*|\tilde{Q}|^2)\|_{L_{t,x}^{\infty}\left([a,b]\times \Omega_j\right)}.
\end{align}

On the other hand, by  changing of variables, 
\[
|x|^{-2}*|\tilde{Q}|^2=\frac{1}{\lambda(t)^2}\phi_{Q^2}\Big(\frac{x}{\lambda(t)}-\frac{x(t)}{\lambda(t)}\Big).
\]
Let $x_\ast=\sup_{t\in[a,b]}|x(t)|$. By
Proposition~\ref{grondstate1} and $\lambda(t)\geq1$,
\[
\frac{1}{\lambda(t)^2}
\phi_{Q^2}\left(\frac{x-x(t)}{\lambda(t)}\right)
\lesssim\frac{1}{\lambda(t)^2+|x-x(t)|^2}.
\]
Hence
\begin{align}\label{th1}
&\sum_{j\in\mathbb Z}2^j
\big\||x|^{-2}*|\widetilde Q|^2\big\|_{L_{t,x}^\infty([a,b]\times\Omega_j)}
\notag\\
&\qquad\lesssim
\sum_{2^j\leq4(1+x_\ast)}2^j
+\sum_{2^j>4(1+x_\ast)}2^{-j}
\lesssim1+x_\ast\lesssim T^{1/25}.
\end{align}
Inserting the above estimate into \eqref{f5.21}, then
\begin{align} \label{final1}\eqref{equ:pi-4up-2v}
&\lesssim T^{1/25}2^{-i}\|P_{\geq i-4}u\|_{U_{\Delta}^2\left([a,b]\right)}.
\end{align}

{\bf The estimate of \eqref{equ:pi-4Qpi-2v}:}
Set
\[
W(t,x)=\lambda(t)^{-d/2}
\left(1+\left|\frac{x-x(t)}{\lambda(t)}\right|^2\right)^{-50d}.
\]
By the decay of $Q$, the kernel estimate for $P_{\leq i-4}$, and
$2^{i-4}\lambda(t)\geq1$,
\begin{equation}\label{local:projected-Q}
|\widetilde Q(t,x)|+|P_{\leq i-4}\widetilde Q(t,x)|\lesssim W(t,x).
\end{equation}
By H\"older's inequality, the Hardy--Littlewood--Sobolev inequality,
and \eqref{f5.20},
\begin{align}\notag
\eqref{equ:pi-4Qpi-2v}
&\lesssim 2^{-i/2}\sum_{j\in\mathbb Z}2^{j/2}
\|W\|_{L_t^\infty L_x^{\frac{2d}{d-2}}([a,b]\times\Omega_j)}
\big\||x|^{-2}*|\widetilde QP_{\geq i-4}u|\big\|_{L_t^2L_x^d}\notag\\
&\lesssim 2^{-i/2}\sum_{j\in\mathbb Z}2^{j/2}
\|W^{2/d}\|_{L_{t,x}^\infty([a,b]\times\Omega_j)}
\|WP_{\geq i-4}u\|_{L_t^2L_x^{\frac{d}{d-1}}}\notag\\
&\lesssim 2^{-i/2}\sum_{j\in\mathbb Z}2^{j/2}
\|W^{2/d}\|_{L_{t,x}^\infty([a,b]\times\Omega_j)}
\|W^{2/d}P_{\geq i-4}u\|_{L_{t,x}^2}.\label{cccv}
\end{align}
Here $\|W^{(d-2)/d}\|_{L_t^\infty L_x^{2d/(d-2)}}$
is bounded uniformly. Since
\[
W(t,x)^{2/d}\lesssim\frac{1}{\lambda(t)+|x-x(t)|},
\]
we have
\begin{align}\label{zznn1}
&\sum_{j\in\mathbb Z}2^{j/2}
\|W^{2/d}\|_{L_{t,x}^\infty([a,b]\times\Omega_j)}\notag\\
&\qquad\lesssim
\sum_{2^j\leq 4(1+x_\ast)}2^{j/2}
+\sum_{2^j>4(1+x_\ast)}2^{-j/2}
\lesssim(1+x_\ast)^{1/2}\lesssim T^{1/50}.
\end{align}
Applying local smoothing once more, we obtain
\begin{align}\notag
\|W^{2/d}P_{\geq i-4}u\|_{L_{t,x}^2}
&\leq\sum_{j\in\mathbb Z}
\|W^{2/d}\|_{L_{t,x}^\infty([a,b]\times\Omega_j)}
\|P_{\geq i-4}u\|_{L_{t,x}^2([a,b]\times\Omega_j)}\notag\\
&\lesssim 2^{-i/2}T^{1/50}
\|P_{\geq i-4}u\|_{U_\Delta^2([a,b])}.\label{znn2}
\end{align}
Inserting \eqref{zznn1} and \eqref{znn2} into \eqref{cccv} yields
\begin{align}\label{final2}
\eqref{equ:pi-4Qpi-2v}
\lesssim 2^{-i}T^{1/25}
\|P_{\geq i-4}u\|_{U_\Delta^2([a,b])}.
\end{align}
Now we collect estimates \eqref{vvv1}, \eqref{mmty}, \eqref{final1} and \eqref{final2}. In view of \eqref{cbz},  we can finally obtain 
\begin{align*}
&\|P_{\geq i}u\|_{U_{\Delta}^2([a,b])}\\
