We start by recalling the standard Morawetz action. Let $a$ be a spatial function and $u$ satisfy
\begin{equation}\label{equ:usateq}
    i\partial_tu+\Delta u=\mathcal{N}_1,
\end{equation}
on $I\times\mathbb{R}^d.$ For $t\in I$, we define the Morawetz action
$$M_a(t):=\int_{\mathbb{R}^d}\nabla a(x)\cdot \operatorname*{Im} \big(\bar{u}\nabla u\big)(t,x)\, {d}x.$$
A simple computation shows
\begin{lemma}[Morawetz identity]\label{lem:moriden}
We have
\begin{align*}
\frac{d}{dt}M_a(t)=\frac12\int_{\mathbb{R}^d}(-\Delta\Delta
a)|u|^2dx+2\int_{\mathbb{R}^d}a_{jk}\operatorname*{Re}(\partial_j\bar{u}\partial_ku)dx+\int_{\mathbb{R}^d}a_j(x)\{\mathcal{N}_1,u\}_P^jdx
\end{align*}
where the momentum bracket  $\{f,g\}_P=\operatorname*{Re}(f\nabla\bar{g}-g\nabla\bar{f}),$  and repeated indices are implicitly summed.
\end{lemma}

Let $\vartheta(r) \in C^{\infty}([0, \infty))$ be a nonnegative,
nonincreasing cutoff satisfying $\vartheta(r) = 1$ for $0 \leq r \leq 1$
and $\vartheta(r)=0$ for $r\geq2$. Then let
\begin{equation*} 
\phi(r) = \int_{0}^{r} \psi \left(\frac{s}{2R} \right)  \, {d} s, \quad\psi(r):=\vartheta^2(r),
\end{equation*}
and we define the Morawetz action 
\begin{equation}\label{f7.4}
M(t) = \int_{\mathbb{R}^d} \phi(|x|) \frac{x}{|x|} \cdot \operatorname*{Im} \left[\overline{P_{\leq k_0+ 4} u} \nabla P_{\leq k_0+4} u \right](t,x) \,   {d} x.
\end{equation}
Letting $v=P_{\leq k_0+4} u$, it solves 
\begin{equation}\label{equ:vsolequ}
i \partial_{t} v + \Delta v +  {F}(v)
 =  F(v) - P_{\leq k_0+4}  {F} (u) := -{\mathcal{N}},
\end{equation}
with $F(v)=(|x|^{-2}\ast|v|^2)v.$

\begin{remark}\label{rem:Moraweig}
 Taking $\nabla a(x)=\phi(|x|) \frac{x}{|x|}$, we obtain
 \begin{align*}
  a_{jk}(x)=&
  \phi'(|x|)\tfrac{x_jx_k}{|x|^2}+\frac{\phi(|x|)}{|x|}\big(\delta_{jk}-\tfrac{x_jx_k}{|x|^2}\big)\\
  =&\vartheta^2\big(\tfrac{|x|}{2R}\big)\delta_{jk}
  +\Big[\frac{\phi(|x|)}{|x|}-\vartheta^2\big(\tfrac{|x|}{2R}\big)\Big]\big(\delta_{jk}-\tfrac{x_jx_k}{|x|^2}\big),\\
 \Delta a=&\phi'(|x|)+\frac{d-1}{|x|}\phi(|x|),\\
 \Delta\Delta a=&\phi^{(3)}+(d-1)\big(\tfrac{\phi''}{|x|}-\tfrac{2\phi'}{|x|^2}+\tfrac{2\phi}{|x|^3}\big)+\tfrac{d-1}{|x|}\Big[\phi''+(d-1)\big(\tfrac{\phi'}{|x|}-\tfrac{\phi}{|x|^2}\big)\Big]\\
 =&\psi''\big(\tfrac{r}{2R}\big)\tfrac{1}{4R^2}+O\big(\tfrac{1}{R^2}\mathbf{1}_{|x|\geq 2R}\big)=O\big(\tfrac{1}{R^2}\mathbf{1}_{|x|\geq 2R}\big),
 \end{align*}
 and due to the symmetry of convolution,
 \begin{align*}
&\int_{\mathbb{R}^d}\nabla a(x)\cdot \{F(v),v\}_P\; dx\\
=& -\frac{1}{2}\iint \big(\nabla a(x)-\nabla a(y)\big)\cdot \nabla_x \big(|x-y|^{-2}\big)|v(x)|^2|v(y)|^2\ dxdy.
 \end{align*}
\end{remark}

By  Lemma \ref{lem:moriden} and Remark \ref{rem:Moraweig}, we get
\begin{align}\label{estq3}
 \frac{d}{dt}M(t)=&O\Big(\tfrac{1}{R^2}\int_{|x|\geq 2R}|v|^2\;dx\Big)\\  \label{estq2}
 &+2\operatorname*{Re} \int_{\mathbb{R}^d} \Big[\frac{\phi(|x|)}{|x|}-\vartheta^2\big(\tfrac{|x|}{2R}\big)\Big]\big(\delta_{jk}-\tfrac{x_jx_k}{|x|^2}\big)\big(\partial_j\bar{v}\partial_kv\big)\;dx\\\label{equ:Marterm3}
 &+2\int_{\mathbb{R}^d} \vartheta^2\big(\tfrac{|x|}{2R}\big)|\nabla v|^2\;dx
 \\\label{equ:Marterm4}
 &+\frac{1}{2}\iint \big(\nabla a(x)-\nabla a(y)\big)\cdot \nabla_x \big(|x-y|^{-2}\big)|v(x)|^2|v(y)|^2\ dxdy\\\label{estq4}
 &-\int_{\mathbb{R}^d} \phi(|x|)\frac{x}{|x|}\cdot \big\{\mathcal{N},v\big\}_P\;dx.
\end{align}

{\bf Step 1: Estimation of $M(b) - M(a)$.}
Recalling the decomposition
\begin{align}\notag
    u(t,x)=&e^{-i\gamma(t)}e^{-i\frac{x-x(t)}{\lambda(t)}\cdot\xi(t)}\lambda(t)^{-\frac{d}{2}}
    \Big(\epsilon\big(t,\tfrac{x-x(t)}{\lambda(t)}\big)+Q\big( \tfrac{x-x(t)}{\lambda(t)}\big)\Big)\\\label{equ:uepsQ1}
    \triangleq&\tilde{\epsilon}(t,x)+\tilde{Q}(t,x),
\end{align}
we have
\begin{align*}
 M(t)=&\int_{\mathbb{R}^d}\phi(|x|)\frac{x}{|x|}\cdot \operatorname*{Im}\Big[\overline{P_{\leq k_0+4}(\tilde{Q}+\tilde{\epsilon})}\nabla P_{\leq k_0+4} (\tilde{Q}+\tilde{\epsilon})\Big]\;dx\\
 =&\int_{\mathbb{R}^d}\phi(|x|)\frac{x}{|x|}\cdot \operatorname*{Im}\Big[\overline{P_{\leq k_0+4}\tilde{Q}}\nabla P_{\leq k_0+4} \tilde{Q}\Big]\;dx\\
 &+\int_{\mathbb{R}^d}\phi(|x|)\frac{x}{|x|}\cdot \operatorname*{Im}\Big[\overline{P_{\leq k_0+4}\tilde{\epsilon}}\nabla P_{\leq k_0+4}\tilde{Q}\Big]\;dx\\
 &+\int_{\mathbb{R}^d}\phi(|x|)\frac{x}{|x|}\cdot \operatorname*{Im}\Big[\overline{P_{\leq k_0+4}\tilde{Q}}\nabla P_{\leq k_0+4} \tilde{\epsilon}\Big]\;dx\\
 &+\int_{\mathbb{R}^d}\phi(|x|)\frac{x}{|x|}\cdot \operatorname*{Im}\Big[\overline{P_{\leq k_0+4}\tilde{\epsilon}}\nabla P_{\leq k_0+4} \tilde{\epsilon}\Big]\;dx\\
 \triangleq&M_1(t)+M_2(t)+M_3(t)+M_4(t).
\end{align*}

{\bf The estimate of the term $M_1(b)-M_1(a)$:}
By \eqref{equ:uepsQ}, $Q$ is real-valued and
\[
\operatorname*{Im}\bigl(\overline{\widetilde Q}\nabla\widetilde Q\bigr)
=-\frac{\xi(t)}{\lambda(t)}|\widetilde Q|^2.
\]
Using \eqref{large1}, $x(a)=\xi(b)=0$, and the radiality of $Q$,
we obtain
\begin{align}\label{qqw1}
M_1(b)-M_1(a)
={}&-\left.\frac{1}{\lambda(t)^d}
\int\phi(|x|)\frac{x}{|x|}\cdot\frac{\xi(t)}{\lambda(t)}
Q\left(\frac{x-x(t)}{\lambda(t)}\right)^2\,dx\right|_a^b
\notag\\
&+O(R2^{-100k_0})=O(T^{-10}).
\end{align}

{\bf The estimate of the term $M_2(b)-M_2(a)$:} 
Let $\theta(x)=\phi(|x|)x/|x|$. Since
$\|\partial^\alpha\theta\|_{L^\infty}\lesssim_\alpha R^{1-|\alpha|}$,
Proposition~\ref{grondstate2} and Bernstein's inequality give
\begin{align}\label{subqa}
&\left|\int\overline{P_{\leq k_0+4}\widetilde\epsilon},
\theta\cdot\nabla P_{\leq k_0+4}\widetilde Q\,dx
-\int\overline{\widetilde\epsilon},
\theta\cdot\nabla\widetilde Q\,dx\right|\notag\\
&\quad\leq\|\widetilde\epsilon\|_{L_x^2}
\left(\|P_{\geq k_0+4}(\theta\cdot\nabla P_{\leq k_0+4}\widetilde Q)\|_{L_x^2}
+\|\theta\cdot\nabla P_{\geq k_0+4}\widetilde Q\|_{L_x^2}\right)\notag\\
&\quad\lesssim R2^{-100k_0}\|\epsilon(t)\|_{L_x^2}
\lesssim T^{-10}.
\end{align}
Writing $\epsilon=\epsilon_1+i\epsilon_2$ and using \eqref{equ:uepsQ},
we obtain
\begin{align}\label{f7.15}
M_2(b)-M_2(a)
={}&-\left.\int\theta(x)\cdot\frac{\xi(t)}{\lambda(t)}
\frac{\epsilon_1(t,y)Q(y)}{\lambda(t)^d}\,dx\right|_a^b
\notag\\
&-\left.\frac{1}{\lambda(t)}\int\theta(x)\cdot
\frac{\epsilon_2(t,y)\nabla Q(y)}{\lambda(t)^d}\,dx\right|_a^b
+O(T^{-10}),
\end{align}
where $y=(x-x(t))/\lambda(t)$.
On the other hand, since $\phi(|x|)=|x|$ for $|x|\leq 2R$ and by conditions \eqref{equ:assumpxixcond}, we have
$$ \left\|\frac{1}{\lambda(t)^{d/2}}|x|Q \left(\frac{x-x(t)}{\lambda(t)} \right) \right\|_{L_x^2(|x|\geq 2R)} \lesssim T^{-100},$$ 
then by H\"older's inequality and $x(a)=\xi(b)=0$,
\begin{align}\notag
&\left.\int\theta(x)\cdot\frac{\xi(t)}{\lambda(t)}
\frac{\epsilon_1(t,y)Q(y)}{\lambda(t)^d}\,dx\right|_a^b\\
&\quad=\left.\xi(t)\cdot\int x\epsilon_1(t,x)Q(x)\,dx\right|_a^b\notag\\
&\qquad+\left.\frac{x(t)\cdot\xi(t)}{\lambda(t)}
\int\epsilon_1(t,x)Q(x)\,dx\right|_a^b+O(T^{-10})\notag\\
&\quad=-\xi(a)\cdot\int x\epsilon_1(a,x)Q(x)\,dx
+O(T^{-10}).\label{subqa1}
\end{align}
Recalling that $ \left({\epsilon},i\partial_{x_j}Q\right)_{L^2_x}= 0$, $j=1\cdots,d$,
we also have
\begin{align}\notag
	& \frac{1}{\lambda(t)}\int \phi(|x|) \frac{x}{|x|}
\cdot \left[ \frac{1}{\lambda(t)^{d/2}} \epsilon_2 \left(t,\frac{x - x(t)}{\lambda(t)} \right)  \frac{1}{\lambda(t)^{d/2}} \nabla Q \left(\frac{x - x(t)}{\lambda(t)} \right)\right] \,{d}x \Bigg|_{a}^b \\\notag
	=&\int \epsilon_2(t,x) x\cdot\nabla Q(x) \, {d} x \Big|_a^b+ \frac{1}{\lambda(t)}\int \epsilon_2(t,x)x(t)\cdot \nabla Q(x) \, {d} x \Big|_a^b 
+O \left(T^{-10} \right) \\\label{subqa2}
	=& \int \epsilon_2(t,x) x\cdot\nabla Q(x) \, {d} x \Big|_a^b+O \left(T^{-10} \right).
\end{align}
Substituting \eqref{subqa}, \eqref{subqa1} and \eqref{subqa2} into \eqref{f7.15} and then using H\"older's inequality along with 
 \eqref{equ:assumpxixcond}, we deduce that
\begin{align}\label{f7.19}
	&M_2(b)-M_2(a)\\\notag
	=&\xi(a)\cdot \int \epsilon_1(a,x) xQ(x)\, {d}x- \int \epsilon_2(t,x) x\cdot\nabla Q(x) \, {d} x \Bigg|_a^b+O \left(T^{-10} \right) \\\notag
	=& -\left( \epsilon_2(t,x),x\cdot\nabla Q  \right)_{L_x^2} \Big|_a^b+O \left( \|\epsilon\|^2_{L_x^2}
+|\xi(a)|^2 \right)+O(T^{-10}) \\\notag
	=&-\left( \epsilon_2(t,x),x\cdot\nabla Q(x)  \right)_{L_x^2} \Big|_a^b
\\\notag
& \quad +O \left(\frac{2^{2k_0} T^{1/50}}{ T} \int_{J}  \left\| \epsilon(t)  \right\|_{L^2_{x}}^{2} \lambda(t)^{-2} \, {d} t
 +T^{1/50}\sup_{t \in J} \frac{|\xi(t)|^{2}}{\lambda(t)^{2}} + 2^{2k_0} T^{1/50} T^{-10} \right).
\end{align}

{\bf The estimate of the term $M_3(b)-M_3(a)$:}
Similarly, one can verify that
\begin{align}\label{f7.20}
	&M_3(b)-M_3(a)\\\notag
	=&-\left( \epsilon_2(t,x),x\cdot\nabla Q(x)+dQ  \right)_{L_x^2} \Big|_a^b\\ \notag 
    & \quad 
+O \left(\frac{2^{2k_0} T^{1/50}}{ T} \int_{J}
\|\epsilon(t)\|_{L^2_{x}}^{2} \lambda(t)^{-2} \, {d} t + T^{1/50} \sup_{t \in J} \frac{|\xi(t)|^{2}}{\lambda(t)^{2}} + 2^{2k_0} T^{1/50}T^{-10} \right). 
\end{align}

{\bf The estimate of the term $M_4(b)-M_4(a)$:} by Corollary \ref{c4.3} and \eqref{equ:assumpxixcond}, 
\begin{align}\label{f7.21}
	&|M_4(b)-M_4(a)|\\ \notag 
	\lesssim& \|\phi\|_{L^{\infty}}\sup_{t\in J}
\|\epsilon(t)\|_{L^2_x} \cdot\sup_{t\in J}
\left\|\nabla P_{\leq k_0+4}
\left( e^{-i(x-x(t)) \cdot \frac{\xi(t)}{\lambda(t)}} \frac{1}{\lambda(t)^{d/2}} \epsilon \left(t,\frac{x - x(t)}{\lambda(t)} \right) \right) \right\|_{L_x^2}\\\notag
	\lesssim& R \left(\frac{2^{2k_0} T^{1/50}}{ T} \int_{J}
\|\epsilon(t)\|_{L^2_{x}}^{2} \lambda(t)^{-2}  \, {d} t + T^{1/50} \sup_{t \in J} \frac{|\xi(t)|^{2}}{\lambda(t)^{2}} + 2^{2k_0}T^{1/50} T^{-10} \right)\\\notag
	\lesssim& \frac{2^{2k_0} T^{1/10}}{T} \int_{J} \| \epsilon(t)  \|_{L^2_{x}}^{2} \lambda(t)^{-2} \, {d} t
+ T^{1/10} \sup_{t \in J} \frac{|\xi(t)|^{2}}{\lambda(t)^{2}} + 2^{2k_0} T^{1/10}T^{-10}. 
\end{align}


Thus, by \eqref{qqw1}, \eqref{f7.19}, \eqref{f7.20} and \eqref{f7.21}, we obtain
\begin{align}\label{f7.22}
&	M(b) - M(a) \\\nonumber
= &  2 \big( \epsilon_2(a), x \cdot \nabla Q+\tfrac{d}{2}Q\big)_{L^2_{x}}
- 2 \big( \epsilon_2(b),  x \cdot \nabla Q+\tfrac{d}{2}Q \big)_{L^2_{x}} \\\nonumber
& + O \left(\frac{2^{2k_0} T^{1/10}}{T} \int_{J} \|\epsilon(t) \|_{L^2_{x} }^{2} \lambda(t)^{-2}  \, {d} t
+ T^{1/10} \sup_{t \in J} \frac{|\xi(t)|^{2}}{\lambda(t)^{2}} + 2^{2k_0} T^{1/10} T^{-10} \right).
\end{align}

{\bf Step 2: Estimation of  $\frac{ {d} }{ {d} t}M(t)$ and conclusion of the proof.}
 We will estimate the terms \eqref{estq3}-\eqref{estq4} separately. 

{\bf Estimate of  \eqref{estq4}.}
Noticing that, we can always further decompose  nonlinear term $\mathcal{N}$ as $\mathcal{N}_1+\mathcal{N}_2$,  where $\mathcal{N}_1$ contains at least two high-frequency factors (i.e. Fourier supported on $|\xi|\gtrsim 2^{k_0}$) while $\mathcal{N}_1$ itself has Fourier support on $|\xi|\lesssim 2^{k_0}$, and $\mathcal{N}_2$ contains one high-frequency factor  while $\mathcal{N}_2$ itself has Fourier support on $|\xi|\sim 2^{k_0}$.

For the first case, by applying the Hölder inequality and the Hardy-Littlewood-Sobolev inequality, and utilizing the long-time Strichartz estimates for the two high-frequency factors (Theorem \ref{longtime}), then similar to \eqref{bbv}, one can easily obtain that
\begin{align}\nonumber
\int_a^b\Big| \int_{\mathbb{R}^d} \phi(|x|)\frac{x}{|x|}\cdot \big\{\mathcal{N}_1,v\big\}_P\;dx\Big|\,dt
 \lesssim&  2^{k_0} R  \|P_{\gtrsim k_0}u\|^2_{U_{\Delta}^{2}(J)} \\ \label{f7.24}
 \lesssim& 2^{k_0} R  \left(\frac{1}{T} \int_{a}^{b}  \| \epsilon(t) \|_{L^2_{x}}^{2} \lambda(t)^{-2}  \, {d} t +  T^{-10} \right).
\end{align}



For the second case, set $\theta(x)=\phi(|x|)x/|x|$, with
$\theta(0)=0$. This vector field is smooth and satisfies
$\|\partial^\alpha\theta\|_{L^\infty}\lesssim_\alpha
R^{1-|\alpha|}$ for every multi-index $\alpha$.
Applying Bernstein's inequality to $\theta$ and using
$\|u\|^q_{L_t^qL_x^r([a,b]\times\mathbb R^d)}\lesssim T$
for admissible $(q,r)$ with $q<\infty$, we obtain

\begin{align}\label{10.10}
 & \int_a^b\Big| \int_{\mathbb{R}^d} \phi(|x|)\frac{x}{|x|}\cdot \big\{\mathcal{N}_2,v\big\}_P\;dx\Big|\,dt
  \lesssim  2^{-99k_0} \left\| P_{\geq k_0 + 3} |\nabla|^{100}\theta(x)  \right\|_{L^{\infty}_x }T
  \lesssim  {T^{-20}}.
\end{align}
Combining \eqref{f7.24} and \eqref{10.10}, we obtain 
\begin{align}\label{estq41}
	\int_a^b|\eqref{estq4}| \, {d} t
\lesssim 2^{k_0} R \left(\frac{1}{T} \int_{J}  \| \epsilon(t)  \|_{L^2_{x} }^{2} \lambda(t)^{-2}  \, {d} t+T^{-10} \right).
\end{align}

{\bf Estimate of \eqref{estq2}}:
Since $\vartheta$ is nonincreasing, the matrix
\[
\left(\frac{\phi(r)}{r}-\vartheta^2\left(\frac{r}{2R}\right)\right)
\left(\delta_{jk}-\frac{x_jx_k}{|x|^2}\right),\qquad r=|x|,
\]
is positive semidefinite. Therefore,
\begin{align}\label{estq21}
	\eqref{estq2}\geq 0.
\end{align}

{\bf Estimate of \eqref{estq3}}:
Noticing that 
$ \left\|\chi_{|x|\geq 2R}\frac{1}{\lambda(t)^{d/2}}Q \left(\frac{x-x(t)}{\lambda(t)} \right) \right\|_{L_x^2}\lesssim T^{-100}$, by \eqref{equ:assumpxixcond}, we have 
\begin{align}\label{f7.32}
	& \frac{1}{R^{2}} \int_{|x|\geq 2R} 
\left|P_{\leq k_0+4}  \left(e^{-i \gamma(t)} e^{-i(x-x(t)) \cdot \frac{\xi(t)}{\lambda(t)}} \frac{1}{\lambda(t)^{d/2}}Q \left(\frac{x - x(t)}{\lambda(t)} \right) \right) \right|^{2} \, {d} x \notag \\
  \lesssim&	\frac{1}{R^2T^{100}}\lesssim\frac{1}{\lambda(t)^2T^{10}}.
\end{align}
On the other hand, by \eqref{equ:assumpxixcond}, for  sufficiently large $T$, we have
\begin{align}\label{f7.33}
	& \frac{1}{R^{2}}\int  \left|P_{\leq k_0+4} \left(e^{-i \gamma(t)} e^{-i(x-x(t)) \cdot \frac{\xi(t)}{\lambda(t)}}\frac{1}{\lambda(t)^{d/2}} \epsilon \left(t, \frac{x - x(t)}{\lambda(t)} \right) \right)  \right|^{2} \, {d} x \notag \\
 \lesssim&  \frac{1}{R^2} \| \epsilon(t) \|_{L^2_{x} }^{2}
\lesssim \frac{1}{T^{1/25}\lambda(t)^2}  \|\epsilon(t)\|_{L^2_{x}}^{2}.
\end{align}
Therefore,  \eqref{f7.32} and \eqref{f7.33} imply that
\begin{align}\label{estq31}
	|\eqref{estq3}|\lesssim \frac{1}{T^{1/25}\lambda(t)^2} \|\epsilon(t) \|^2_{L^2_x}+O(\frac{1}{\lambda(t)^2T^{10}}).
\end{align}

{\bf Estimate of $\eqref{equ:Marterm3}+\eqref{equ:Marterm4}$:}
We claim that
\begin{align}\label{finalz}
&\int_a^b\eqref{equ:Marterm3}+\eqref{equ:Marterm4}\ dt
 \gtrsim \int_a^b\frac{\|\epsilon(t)\|^2_{L_x^2}}{\lambda(t)^2}\,dt
 -O\Big(\int_a^b\Big|\frac{\xi(t)}{\lambda(t)}\Big|^2
       \|\epsilon(t)\|^2_{L_x^2}\,dt\Big)-O(T^{-8}).
\end{align}
Next, we prove Theorem \ref{t7.13} by assuming that the above claim holds.
Indeed, if \eqref{finalz} holds, then by estimates \eqref{estq41}, \eqref{estq21} and \eqref{estq31} and the fundamental theorem of calculus, we see that for all large $T$, then
\begin{align} \int_{a}^b\frac{\|\epsilon(t)\|^2_{L_x^2}}{\lambda(t)^{2}}\, {d}t  \leq&   2 \big( \epsilon_2(a), x \cdot \nabla Q+\tfrac{d}{2}Q\big)_{L^2_{x}}
- 2 \big( \epsilon_2(b),  x \cdot \nabla Q+\tfrac{d}{2}Q \big)_{L^2_{x}}\notag \\\label{equ:2k0RT}
&  +O\Big(\frac{2^{k_0} R}{T} \int_a^b  \frac{\| \epsilon(t)  \|_{L^2_{x} }^{2}}{\lambda(t)^2}  \, {d} t+\frac{2^{2k_0} T^{1/10}}{T} \int_a^b \frac{\|\epsilon(t) \|_{L^2_{x} }^{2}}{ \lambda(t)^2}  \, {d} t\Big)\\\notag
&+O\Big(\frac{2^{k_0} R}{T^{10}}+ T^{1/10} \sup_{t \in J} \frac{|\xi(t)|^{2}}{\lambda(t)^{2}} + 2^{2k_0} T^{1/10} T^{-10}+T^{-8} \Big).
\end{align}
Since $R=T^{2/25}=2^{6k_0/25}$, we have
\[
\frac{2^{k_0}R}{T}=T^{-44/75},\qquad
\frac{2^{2k_0}T^{1/10}}{T}=T^{-7/30}.
\]
Thus the term \eqref{equ:2k0RT} can be absorbed in the left-hand side
for $T$ sufficiently large, which implies \eqref{f7.2}. Therefore, we complete the proof of Theorem \ref{t7.13} provided that the claim \eqref{finalz} holds.


{\bf Step 3: proof of the claim \eqref{finalz}.}     
Set $\vartheta_R(x)=\vartheta(|x|/R)$ and define the symmetric remainder kernel
\[
 B_R(x,y)=-\frac12\bigl(\nabla a(x)-\nabla a(y)\bigr)
             \cdot\nabla_x|x-y|^{-2}
          -\vartheta_R(x)^2\vartheta_R(y)^2|x-y|^{-2}.
\]
Since $\nabla a(x)=x$ for $|x|\leq2R$ and $\nabla a$ is
uniformly Lipschitz, we have
\[
 |B_R(x,y)|\lesssim |x-y|^{-2}
      \mathbf{1}_{\{\max(|x|,|y|)\geq R\}}.
\]
The nonlinear virial contribution therefore admits the exact decomposition
\begin{align}
&\int_{\mathbb{R}^d}\nabla a(x)\cdot\{F(v),v\}_P\,dx\notag\\
=&-\frac12\iint_{\mathbb{R}^{2d}}
 \bigl(\nabla a(x)-\nabla a(y)\bigr)\cdot\nabla_x|x-y|^{-2}
 |v(x)|^2|v(y)|^2\,dxdy\notag\\
=&\iint_{\mathbb{R}^{2d}}|x-y|^{-2}
 |\vartheta_R(x)v(x)|^2|\vartheta_R(y)v(y)|^2\,dxdy\label{vvc1}\\
&+\iint_{\mathbb{R}^{2d}}B_R(x,y)|v(x)|^2|v(y)|^2\,dxdy.
 \label{vvc2}
\end{align}
We can further decompose \eqref{vvc2} as
\[
\eqref{vvc2}=\mathcal{A}_{0,1}+\mathcal{A}_{0,2}+\mathcal{A}_{0,3},
\]
where the term $\mathcal{A}_{0,1}$ contains the terms in which at least one ground-state factor is evaluated in $\{|x|\geq R\}$, $\mathcal{A}_{0,3}$ contains the terms that have at least three $\epsilon$ terms, and $\mathcal{A}_{0,2}$ contains the other terms in this decomposition. Noticing that by the Pigeonhole Principle, the term $\mathcal{A}_{0,2}$ must have the following form 
\[
c\iint_{|x|\leq R, |y|\geq R} B_R(x,y)|P_{\leq k_0+4}\tilde{Q}(x)|^2|P_{\leq k_0+4}\tilde{\epsilon}(y)|^2\,dxdy
\]
for some constant $c$. Using the bound on $B_R$ and Hardy's inequality, we obtain
\begin{align}
    |\mathcal{A}_{0,2}|\lesssim& \iint_{\frac{R}{4}\leq|x|\leq R, \ |y|\geq R} |x-y|^{-2}|P_{\leq k_0+4}\tilde{Q}(x)|^2|P_{\leq k_0+4}\tilde{\epsilon}(y)|^2\ dxdy\notag\\
    &+\iint_{|x|\leq \frac{R}{4}, \ |y|\geq R} |x-y|^{-2}|P_{\leq k_0+4}\tilde{Q}(x)|^2|P_{\leq k_0+4}\tilde{\epsilon}(y)|^2\ dxdy\notag\\
    \lesssim& \left(\frac{1}{\lambda(t)^2T^{10}}+\frac{1}{R^2}\right)
\|\epsilon(t)\|_{L_x^2}^2\notag\\
    \lesssim& \frac{\|\epsilon(t)\|^2_{L_x^2}}{\lambda(t)^2T^{10}}
+\frac{1}{\lambda(t)^2R}\|\epsilon(t)\|^2_{L_x^2}.
\end{align}
By \eqref{equ:assumpxixcond}, $R/\lambda(t)\geq T^{7/100}$
and $|x(t)|\leq R^{1/2}$. Proposition~\ref{grondstate2} and
Bernstein's inequality give
\begin{equation}\label{virial:Q-tail}
\begin{aligned}
&\|\nabla P_{\leq k_0+4}\widetilde Q\|_{L_x^2(|x|\geq R/8)}
+R^{-1}\|P_{\leq k_0+4}\widetilde Q\|_{L_x^2(|x|\geq R/8)}\\
&\qquad\lesssim\frac{1}{\lambda(t)T^{100}}.
\end{aligned}
\end{equation}
The preceding estimate follows by applying Hardy's inequality to
a smooth spatial cutoff and using \eqref{virial:Q-tail}.
Similarly, \eqref{virial:Q-tail} yields
\begin{align}
    |\mathcal{A}_{0,1}|
&\lesssim \Bigl(\|\nabla P_{\leq k_0+4}\widetilde Q\|_{L_x^2(|x|\geq R/2)}
+R^{-1}\|P_{\leq k_0+4}\widetilde Q\|_{L_x^2(|x|\geq R/2)}\Bigr)\notag\\
&\qquad\times\Bigl(\|\nabla P_{\leq k_0+4}\widetilde Q\|_{L_x^2}
+\|\nabla P_{\leq k_0+4}\widetilde\epsilon\|_{L_x^2}\Bigr)\notag\\
&\lesssim \frac{2^{k_0}}{\lambda(t)T^{100}}
\lesssim\frac{1}{\lambda(t)^2T^{20}}.
\end{align}
Finally, for the term $\mathcal{A}_{0,3}$, we just use Hardy-Littlewood-Sobolev's inequality to deduce that
\begin{align}\label{qrr}
   \int_a^b |\mathcal{A}_{0,3}|\, dt&\lesssim \int_a^b\Big(\Big\|\frac{1}{\lambda(t)^{d/2}}\epsilon\big(\frac{x-x(t)}{\lambda(t)}\big)\Big\|^2_{L_x^{\frac{2d}{d-2}}}\|\epsilon\|_{L_x^2}\big(\|\epsilon\|_{L_x^2}+\|Q\|_{L^2}\big)\Big)\, dt\notag\\
    &\lesssim \eta_{\ast}\int_a^b\frac{1}{\lambda(t)^2}\|\epsilon(t)\|^2_{L_x^2}\, dt,
\end{align}
where the last inequality comes from \eqref{estepsilonnorm}. In view of these estimates, we can use the assumptions \eqref{equ:assumpxixcond}(which means that $\lambda(t)^2\ll R$) to deduce that
\begin{align}\notag
\int_a^b\eqref{equ:Marterm3}+\eqref{equ:Marterm4}\, dt&=2\int_a^b\int_{\mathbb{R}^d} \vartheta^{2} \left(\frac{|x|}{2R} \right)
\left|\nabla v\right|^{2} \, dxdt\\\notag
&-\int_a^b\int_{\mathbb{R}^{2d}} |x-y|^{-2}\big|\vartheta(\frac{|x|}{R})v(x)\big|^2\big|\vartheta(\frac{|y|}{R})v(y)\big|^2 \ dxdydt\\
&+O\Big((\eta_{\ast}+\frac{1}{R})\int_a^b\frac{1}{\lambda(t)^2}\|\epsilon(t)\|^2_{L_x^2}\, dt\Big)+O(\frac{1}{T^{8}}).
\end{align}
Therefore, it only remains to estimate the localized energy part
\begin{align}\label{equ:locenerg}
    &2\int_a^b\int_{\mathbb{R}^d} \vartheta^{2} \big(\frac{|x|}{2R} \big)
|\nabla v|^{2} \, dxdt
-\int_a^b\int_{\mathbb{R}^{2d}} |x-y|^{-2}\big|\vartheta(\frac{|x|}{R})v(x)\big|^2\big|\vartheta(\frac{|y|}{R})v(y)\big|^2 \, dxdydt.
\end{align}
Obviously,
\begin{align}\notag
\eqref{equ:locenerg}
    \geq&2\int_a^b\int_{\mathbb{R}^d} \vartheta^{2} \left(\frac{|x|}{R} \right)
\left|\nabla v\right|^{2} \, dxdt\notag\\
&-\int_a^b\int_{\mathbb{R}^{2d}} |x-y|^{-2}\big|\vartheta(\frac{|x|}{R})v(x)\big|^2\big|\vartheta(\frac{|y|}{R})v(y)\big|^2 \ dxdydt\label{pppo}
\end{align}
As before, we can rewrite  \eqref{pppo} as a sum of terms involving $Q$ and $\epsilon$, and then estimate them separately.
For the terms that contain at least three $Q$ in the potential energy or at least one $Q$ in the kinetic energy, we denote them by $\mathcal{A}_1$. Then there must be one $Q$ outside the convolution structure. Hence, by using the smoothness of $Q$, one can easily check that
\begin{align}\label{zzm0}
    \mathcal{A}_1=  \int_a^b\Big(\frac{2|\xi(t)|^{2}}{\lambda(t)^{2}} \| Q \|_{L^2_{x}}^{2} + \frac{2}{ \lambda(t)^{2}}
\|\epsilon(t)\|_{L^2_{x}}^{2} - \frac{2|\xi(t)|^{2}}{\lambda(t)^{2}}  \| \epsilon(t)  \|_{L^2_{x}}^{2} + O \left(2^{2k_0} T^{-10} \right)\Big)\, dt. 
\end{align}
Next, we consider the terms involving at least three $\epsilon$'s, which are denoted as $\mathcal{A}_3$. In this case, similar to the proof of \eqref{qrr}, we can only use the Hardy-Littlewood-Sobolev inequality and H\"older's inequality to obtain 
\begin{align}
    |\mathcal{A}_3|&\lesssim \int_a^b\Big(\Big\|\frac{1}{\lambda(t)^{d/2}}\epsilon\big(\frac{x-x(t)}{\lambda(t)}\big)\Big\|^2_{L_x^{\frac{2d}{d-2}}}\|\epsilon\|_{L_x^2}\big(\|\epsilon\|_{L_x^2}+\|Q\|_{L^2}\big)\Big)\, dt\notag\\
    &\lesssim \eta_{\ast}\int_a^b\frac{1}{\lambda(t)^2}\|\epsilon(t)\|^2_{L_x^2}\, dt.
\end{align}

Finally, we consider the terms involving two $\epsilon$'s, which are denoted as $\mathcal{A}_2$. On one side, by the product rule and Young's inequality, 
we have
\begin{align*}
&\int\vartheta\left(\frac{|x|}{R}\right)^2
|\nabla P_{\leq k_0+4}\widetilde\epsilon|^2\,dx\\
&\quad\geq(1-\delta_0)
\left\|\vartheta\left(\frac{|x|}{R}\right)
P_{\leq k_0+4}\widetilde\epsilon\right\|_{\dot H_x^1}^2
-C\delta_0^{-1}R^{-2}\|\epsilon(t)\|_{L_x^2}^2.
\end{align*}
On the other hand, \eqref{equ:assumpxixcond} and the decay of the
orthogonality functions give
\[
\left|\left(\vartheta\left(\frac{|\lambda(t)x+x(t)|}{R}\right)
\epsilon(t),f\right)_{L_x^2}\right|\lesssim T^{-20},
\]
for every $f\in\{\chi,i\chi,\partial_jQ,i\partial_jQ:1\leq j\leq d\}$.
Applying the coercivity estimate \eqref{midest2} and the estimates leading to \eqref{cccc0} to the localized remainder, we obtain 
\begin{align}\notag
\mathcal{A}_2\geq&
\int_a^b\Big[\left(\frac{2\lambda_{1}}{\lambda(t)^{2}} -\frac{2}{\lambda(t)^{2}} \right)
\| \epsilon(t)\|_{L^2_{x}}^{2}\\
&+ \lambda_{1} \Big\|\vartheta(\frac{|x|}{R})\nabla P_{\leq k_0+4} \left( e^{-i \gamma(t)} e^{-i(x-x(t))\cdot \frac{\xi(t)}{\lambda(t)}} \frac{1}{\lambda(t)^{d/2}} \epsilon\left(t, \frac{x - x(t)}{\lambda(t)} \right) \right)\Big\|^2_{L_x^2}\notag \\\notag
&-\delta_0\left\| \vartheta \left(\frac{|x|}{R} \right) P_{\leq k_0+4} \left(e^{-i \gamma(t)} e^{-i(x-x(t))\cdot \frac{\xi(t)}{\lambda(t)}} \frac{1}{\lambda(t)^{d/2}} \epsilon
\left(t, \frac{x - x(t)}{\lambda(t)} \right) \right)  \right\|_{\dot{H}_x^{1}}^2\\\label{zzm2}
&-\delta_0^{-1}O \left(\frac{1}{R ^2}  \|\epsilon(t)\|_{L^2_{x}}^{2} \right) -O(|\frac{\xi(t)}{\lambda(t)}|^2\|\epsilon(t)\|^2_{L_x^2})\Big]\, dt- O \left(2^{2k_0} T^{-10} \right)
\end{align}
with a constant $0<\lambda_1\ll \frac{1}{2}$. 














Collecting estimates \eqref{zzm0}-\eqref{zzm2}, if we take $\delta_0$ and $\eta_{\ast}$ sufficiently small, then the claim \eqref{finalz} holds and we can conclude the proof of this theorem.

