\tilde{\lambda}(s) = \inf_{\tau \in [0, s]} \lambda(\tau).
\end{equation*}
Then, for any $s \geq 0$,
\begin{equation*} 
1 \leq \frac{\lambda(s)}{\tilde{\lambda}(s)} <e.
\end{equation*}

By contradiction, we suppose that there exist $0 \leq s_{-} \leq s_{+} < \infty$ satisfying
\begin{equation*} 
\frac{\lambda(s_{+})}{\lambda(s_{-})} = e.
\end{equation*}
Then we will show that $u(t)$ is a soliton solution to \eqref{1.1}, which is a contradiction since $\lambda(s)$ is constant in that case.
A simple computation shows
\begin{align*}
\left(\nabla Q, |x|^2 Q \right)_{L^2_{x}} =&  \left( iQ, |x|^2 Q \right)_{L^2_{x}} =  \left( i \nabla Q, |x|^2 Q \right)_{L_x^2} = 0,\\
  \left( \frac{d}{2}Q + x \cdot \nabla Q, |x|^{2} Q \right)_{L^2_{x}} =& -\| |x|Q \|_{L^2_{x}}^{2},\\
 L_{-} \left(|x|^2 Q \right) =& -2dQ - 4 x \cdot \nabla Q.
\end{align*}
Using these identities and Theorem \ref{t8.15}, and by performing modulation calculations similar to those in \cite{D2, D1}, we have
\begin{equation*} 
\begin{aligned}
&(\epsilon(s_+),|x|^2Q)_{L_x^2}
-(\epsilon(s_-),|x|^2Q)_{L_x^2}+\||x|Q\|_{L_x^2}^2\\
&\quad+4\int_{s_-}^{s_+}
\left(\epsilon_2(s),\frac d2Q+x\cdot\nabla Q\right)_{L_x^2}\,ds
=O(\eta_\ast).
\end{aligned}
\end{equation*}
This together with
\begin{equation*}
	\left( \epsilon(s_+), |x|^2Q \right)_{L^2_x } ,  \left( \epsilon(s_-), |x|^2Q \right)_{L^2_x }
\lesssim \sup_{s\in[s_-,s_+]} \left\|\epsilon(s) \right\|_{L^2_x } \left\| |x|^2Q \right\|_{L_x^2}=O(\eta_{\ast})
\end{equation*}
yields
\begin{equation}\label{f9.8}
	\big\| |x| Q  \big\|_{L^2_{x}}^{2} + 4 \int_{s_{-}}^{s_{+}}  \left( \epsilon_2(s), \frac{d}{2}Q + x\cdot\nabla Q \right)_{L^2_{x}} \,{d}s
= O (\eta_{\ast}).
\end{equation}
Therefore, there exists $s' \in [s_{-}, s_{+}]$ such that
\begin{equation}\label{f9.9}
\left( \epsilon_2(s'),  \frac{d}{2}Q + x \cdot \nabla Q \right)_{L^2_{x} } < 0.
\end{equation}
Let $T_{\ast}=\frac{1}{\eta_{\ast}}$, and let $s_j$ have the same meaning as in Theorem \ref{t8.15}. 
Since $s' \geq 0$, there exists a unique $j \geq 0$ such that $s_{j} \leq s'< s_{j + 1}$. Observing that $|s_{j+1}-s_j|\leq C 2^{j}T_{\ast}$, we have  $s_{j+1}\in \left[s',s'+C2^jT_{\ast} \right]$.
By \eqref{f8.4} and the integral mean value theorem, there exists $\tilde{s}_1\in  \left[0,2^jT_{\ast} \right]$ satisfying
\begin{align}\label{f9.10}
	\|\epsilon \left(s'+C2^jT_{\ast}+\tilde{s}_1 \right)\|_{L^2}\lesssim& 2^{-j}\eta_{\ast},\\\label{f9.11}
\int_{s'}^{s'+ C2^{j}T_{\ast}+\tilde{s}_1}  \left\|\epsilon(s) \right\|^2_{L^2_x } \, {d} s
\lesssim 2^{-j}\eta_{\ast},&\quad\int_{s'}^{s'+ C2^{j}T_{\ast}+\tilde{s}_1}  \left\|\epsilon(s) \right\|_{L^2_x }  \, {d} s \lesssim 1,
\end{align}
with implicit constants in \eqref{f9.10} and \eqref{f9.11}  independent of $\eta_{\ast}$. 
Similarly, for any $k\in \mathbb{N}_+$, there exists $\tilde{s}_k\in  \left[0,2^{j+k}T_{\ast} \right]$ such that
\begin{equation*}
s_{j+k+1}\in \Big[s'+C\sum_{i=j}^{j+k-1}2^iT_{\ast}+\sum_{m=1}^{k-1}\tilde{s}_m,\  s'+C\sum_{i=j}^{j+k-1}2^iT_{\ast}+\sum_{m=1}^{k-1}\tilde{s}_m+C2^{k+j}T_{\ast}+\tilde{s}_k\Big],
\end{equation*}
 \begin{equation}\label{f9.13}
	\bigg\|\epsilon \Big(s'+C\sum_{i=j}^{j+k-1}2^iT_{\ast}+\sum_{m=1}^{k-1}\tilde{s}_m+C2^{k+j}T_{\ast}+\tilde{s}_k \Big)\bigg\|_{L_x^2}
\lesssim 2^{-j-k}\eta_{\ast},
\end{equation}
\begin{equation}\label{f9.14}
\begin{aligned}
	\int_{s'+C\sum\limits_{i=j}^{j+k-1}2^iT_{\ast}+\sum\limits_{m=1}^{k-1}\tilde{s}_m}^{s'+C\sum\limits_{i=j}^{j+k}2^iT_{\ast}+\sum\limits_{m=1}^{k}\tilde{s}_m}
\left\|\epsilon(s) \right\|^2_{L^2_x }\, { d} s
&\lesssim 2^{-j-k}\eta_{\ast},\\\int_{s'+C\sum\limits_{i=j}^{j+k-1}2^iT_{\ast}+\sum\limits_{m=1}^{k-1}\tilde{s}_m}^{s'+C\sum\limits_{i=j}^{j+k}2^iT_{\ast}+\sum\limits_{m=1}^{k}\tilde{s}_m} \left\|\epsilon(s) \right\|_{L^2_x } \, {d} s &\lesssim 1,
\end{aligned}
\end{equation}
with implicit constants in \eqref{f9.13} and \eqref{f9.14} independent of $\eta_{\ast}$ and $k$. 
Let $T_k=C\sum_{i=j}^{j+k}2^iT_{\ast}+\sum_{m=1}^{k}\tilde{s}_m$, and  suppose that for any $1\leq k \leq n$, there exists constant $C_0>0$ so that
\begin{equation}\label{qmm}
	\int_{s'}^{s'+T_k}  \left\|\epsilon(s) \right\|^2_{L^2_x } \, {d} s
 \leq C_02^{-j-k}\eta_{\ast},\quad\int_{s'}^{s'+T_k}  \left\|\epsilon(s) \right\|_{L^2_x } \, {d} s \leq C_0,
\end{equation}
then we claim that for $C_{0}$ sufficiently large,
\begin{equation}\label{induction10B}
	\int_{s'}^{s'+T_{k+1}}  \left\|\epsilon(s) \right\|^2_{L^2_x } \, {d} s \leq C_02^{-j-k-1}\eta_{\ast}.
\end{equation}
In fact, by  \eqref{f8.4}, \eqref{f9.14} and \eqref{qmm}, we have
\begin{equation*} 
\int_{s'}^{s'+T_{k+1}}
\left\|\epsilon(s) \right\|^2_{L^2_x } \, {d} s
\leq C_02^{-j-k}\eta_{\ast}+C_12^{-j-k}\eta_{\ast},\quad\int_{s'}^{s'+T_{k+1}}  \left\|\epsilon(s) \right\|_{L^2_x } \, {d} s \leq C_0+C_1
\end{equation*}
for some constant $C_1$, which is also independent of $\eta$ and $k$. As in the proof of Theorem \ref{t7.14}, we can set
\begin{equation*}
	1\leq \lambda(s)\leq T_{k+1}^{1/100},
\quad   s\in \left[s',s'+T_{k+1} \right],\quad \xi \left(s'+T_{k+1} \right)=x \left(s' \right)=0,
\end{equation*}
and by \eqref{f4.54} and \eqref{f4.55},
\begin{equation*}
	\sup_{s\in \left[s',s'+T_{k+1} \right]}\frac{|\xi(s)|}{\lambda(s)}
\lesssim \left(\int_{s'}^{s'+T_{k+1}}  \left\| \epsilon(s) \right\|_{L^2_{x} }^{2} \, { d} s \right)\ll\eta_0.
\end{equation*}
\begin{equation*}
\sup_{s\in[s',s'+T_{k+1}]}|x(s)|\ll T_{k+1}^{1/25}.
\end{equation*}
Noticing that $C2^{j+k+1}T_{\ast}\leq T_{k+1}\leq 4C2^{j+k+1}T_{\ast}$, by Theorem \ref{t7.13} and \eqref{f9.9},
\begin{align}\label{8.45}
& \int_{s'}^{s'+T_{k+1}}  \left\| \epsilon(s) \right\|_{L^2_{x} }^{2} \, {d} s\\\notag
\lesssim&   
\left( \epsilon_2\left(s' \right),  \frac{d}{2}Q + x \cdot \nabla Q \right)_{L^2_{x} } 
+ \left\|\epsilon \left(s'+T_{k+1} \right) \right\|_{L^2_x }\\\notag
&+T_{k+1}^{1/10} \left(\int_{s'}^{s'+T_{k+1}}  \left\| \epsilon(s) \right\|_{L^2_{x} }^{2}  \, {d} s \right)^2+O \left( 
{T_{k+1}^{-8}} \right) \\\notag
\lesssim& 2^{-j-k-1}\eta_{\ast}+T_{k+1}^{1/10} \left(\int_{s'}^{s'+T_{k+1}}  \left\| \epsilon(s) \right\|_{L^2_{x} }^{2}  \, {d} s \right)^2+O \left( { T_{k+1}^{-8}} \right) \\\notag
\lesssim& 2^{-j-k-1}\eta_{\ast}+ \left(4C2^{j+k+1}T_{\ast} \right)^{1/10}\eta_{\ast}^2(C_0+C_1)^22^{-2j-2k}+\frac{1}{C^82^{8j+8k+8}T^8_{\ast}}.
\end{align}
 Moreover, the implicit constant in \eqref{8.45} only relies on that in  \eqref{f9.13} and Theorem \ref{t7.14}, which are both independent of $\eta_{\ast}$ and $k$. 
 Thus, by choosing $\eta_{\ast}$ sufficiently small and $C_0$ sufficiently large, \eqref{induction10B} holds.

Now we let $k \nearrow \infty$, 
 then \eqref{induction10B} implies 
\begin{equation*} 
\int_{s'}^{\infty}  \left\| \epsilon(s) \right\|_{L^2_{x} }^{2} \, {d} s = 0,
\end{equation*}
which directly yields that $ \epsilon (s) = 0$ for all $s \geq s'$. This is a contradiction since $u$ is not a soliton.

\label{t9.17}
If $u$ is the solution in Theorem \ref{t2.3} and
\begin{equation*} 
\sup(I) = \infty,
\end{equation*}
then $u$ is a soliton solution of the form \eqref{soliton}.

If $u$ is not a soliton of the form \eqref{soliton}, then $\sup\limits_{s\in[0,\infty)} \left\|\epsilon(s) \right\|_{L^2_x }>0$. By Remark~\ref{remarkz}, we may first translate time so that
\eqref{weakerc} holds. Then \eqref{f8.32} implies that the remainder
tends to zero. Its positive maximum on the remaining half-line is
therefore attained. Translating once more and relabeling this
maximum as $\eta_\ast$, we obtain 
\begin{align}\label{contra}
\left\|\epsilon(0) \right\|_{L^2_x }=\sup_{s\in[0,\infty)} \left\|\epsilon(s) \right\|_{L^2_x }=\eta_{\ast}.
\end{align}
Additionally, by rescaling, we can set $\tilde{\lambda}(s)\leq  1$ for all $s\geq0$.


\textbf{Case 1.} $\tilde{\lambda}(s)\searrow 0$. In this case, for any integer $k \geq 0$, let
\begin{equation}\label{f10.3}
I(k) =  \left\{ s \geq 0 : 2^{-k + 2} \leq \tilde{\lambda}(s) \leq 2^{-k + 3}  \right\}.
\end{equation}
Since $\sup(I)=\infty$, there exists a sequence $k_{n} \nearrow \infty$ such that
\begin{equation*} 
|I(k_{n})| 2^{-2k_{n}} \geq \frac{1}{k_{n}^{2}},
\end{equation*}
and that $|I(k_{n})| \geq |I(k)|$ for all $k \leq k_{n}$.

Let $I(k_n)=[a_n,b_n]$. We then claim that for any sufficiently large $n$, there exists $s_{n} \in [\frac{3 a_{n} + b_{n}}{4} ,\frac{a_{n} + 3 b_{n}}{4}]\subset I(k_n)$ such that
\begin{equation}\label{f10.5}
\left\| \epsilon(s_{n})  \right\|_{L^2_{x} } \lesssim \frac{1}{|I(k_n)|}.
\end{equation}
Indeed, by Theorem \ref{t8.15},
\begin{equation*}
\int_{I(k_{n})}  \left\| \epsilon(s)  \right\|_{L^2_{x} }^{2}  \, {d} s \lesssim \eta_{\ast},
\end{equation*}
then by the virial identity in \eqref{f9.8}, we have
\begin{equation}\label{f10.7}
\int_{a_{n}}^{\frac{3 a_{n} + b_{n}}{4}}  \left( \epsilon_2, \frac{d}{2}Q + x \cdot \nabla Q \right)_{L^2_{x} } \, {d} s
= O \left(\eta_{\ast} \right) + O(1).
\end{equation}
Therefore, by the integral mean value theorem, there exists $s_{n}^{-} \in  \left[a_{n}, \frac{3 a_{n} + b_{n}}{4} \right]$ such that
\begin{equation}\label{f10.8}
 \left| \left( \epsilon_2 \left(s_{n}^{-} \right), \frac{d}{2}Q + x \cdot \nabla Q \right)_{L^2_{x} } \right| \lesssim \frac{1}{|I(k_{n})|}.
\end{equation}
Similarly, there exists $s_{n}^{+} \in  \left[\frac{a_{n} + 3 b_{n}}{4}, b_{n} \right]$ such that
\begin{equation}\label{f10.9}
 \left| \left( \epsilon_2 \left(s_{n}^{+} \right),\frac{d}{2}Q + x \cdot \nabla Q \right)_{L^2_{x} } \right|
  \lesssim \frac{1}{|I(k_{n})|}.
\end{equation}
Splitting the interval $ \left[s_n^-,s_n^+ \right]$ into $z_n$ small intervals of length $T_{\ast}=\frac{1}{\eta_{\ast}}$, we proceed as follows. 

\textbf{Scenario I.}
If 
 $z_n \leq J=2^{j_{\ast}}$, then, as in \eqref{f8.5}-\eqref{f8.8}, we can similarly prove that
\begin{equation*}
\frac{\sup\limits_{s \in  \left[s_n^-, s_n^+ \right]} \lambda(s)}{\inf\limits_{s \in  \left[s_n^-, s_n^+ \right]} \lambda(s)}
\lesssim e^{\ln (T_{\ast})^{1/4}} \lesssim e^{\ln \left(T_{\ast}^{1/1000} \right)} \ll T_{\ast}^{1/100}.
\end{equation*}
Therefore, after normalizing as in the proof of Theorem~\ref{t7.14}, Theorem~\ref{t7.13} together with \eqref{f10.8} and \eqref{f10.9} implies
\begin{equation*} 
\int_{s_{n}^{-}}^{s_{n}^{+}}  \left\| \epsilon(s)  \right\|_{L^2_{x} }^{2} \, {d} s \lesssim \frac{1}{|I(k_{n})|}.
\end{equation*}

\textbf{Scenario II.}
If  $z_n > J=2^{j_{\ast}}$, then there exists $\ell_n\in\mathbb{N}$ such that $J^{\ell_n}<z_n\leq J^{\ell_n+1}$. Repeating the induction in the proof of Theorem~\ref{t8.15}, using \eqref{f8.17} and \eqref{f8.19}, we obtain
\begin{align*}
	\int_{s_{n}^{-}}^{s_{n}^{+}} \left\| \epsilon(s)  \right\|_{L^2_{x} } \, {d} s\lesssim 1
\end{align*}
and
\begin{align*}
	\int_{s_{n}^{-}}^{s_{n}^{+}} \left\| \epsilon(s) \right\|_{L^2_{x} }^{2} \, {d} s\lesssim J^{1-\ell_n}\eta_{\ast} .
\end{align*}
Following the proof of Theorem \ref{t7.14}, we see that Theorem \ref{t7.13} can be applied on the interval $ \left[s_n^-,s_n^+ \right]$.
Thus \eqref{f10.8} and \eqref{f10.9} imply  
\begin{equation*}
\int_{s_{n}^{-}}^{s_{n}^{+}} \left\| \epsilon(s)  \right\|_{L^2_{x} }^{2}  \, {d} s
\lesssim \frac{1}{|I(k_{n})|} + J^{(\ell_n+1)/10} T_{\ast}^{1/10}J^{1-\ell_n}\eta_{\ast}
 \left(\int_{s_{n}^{-}}^{s_{n}^{+}} \left\| \epsilon(s)  \right\|_{L^2_{x} }^{2}  \, {d} s \right),
\end{equation*}
which further implies
\begin{align*}
\int_{s_{n}^{-}}^{s_{n}^{+}}  \left\| \epsilon(s)  \right\|_{L^2_{x} }^{2} \, {d} s	\lesssim \frac{1}{|I(k_{n})|}, 
\end{align*}
provided $k_n$ is sufficiently large. Thus \eqref{f10.5} holds.

Now, let $m$ be the smallest integer such that
 \begin{equation}\label{f10.12}
 	\frac{2^{2k_{n}}}{k_{n}^{2}} 2^{m} \geq |I(k_{n})|.
 \end{equation}
 Since $|I(k)| \leq |I(k_{n})|$ for all $0 \leq k \leq k_{n}$, \eqref{f10.12} implies that
 \begin{equation}\label{f10.13}
 	|s_{n}| \leq 2^{2k_{n} + m + 1}.
 \end{equation}
 Moreover, as $s_{n} \in [\frac{3 a_{n} + b_{n}}{4} ,\frac{a_{n} + 3 b_{n}}{4}]\subset I(k_n)$, we also have
 \begin{equation}\label{f10.13b}
      |s_{n}| \geq \frac{2^{2k_{n}+m}}{8k_n^2}.
 \end{equation}

 Let $r_{n}$ be the smallest integer satisfying 
 \begin{equation*} 
 	2^{\frac{2k_{n} + m + 1}{3}} \leq 2^{r_{n}}.
 \end{equation*}
Let $t_n=s^{-1}(s_n), \lambda_n=\frac{1}{4}2^{-k_n}$, and set $v_n(t,x)=\lambda_n^{\frac{d}{2}}u \left(\lambda_n^2t,\lambda_nx \right)$. 
After a spatial translation and a Galilean transformation, we continue to denote the resulting solution by $v_n$. Its modulation parameters $\tilde{\xi}(t)$, $\tilde{x}(t)$, and $\tilde{\gamma}(t)$ satisfy
	\begin{align} \label{yyz}
	&e^{i\tilde{\gamma}(t)}e^{ix\cdot\tilde{\xi}(t)}\tilde{\lambda}(t)^{d/2}v_n \left(t,\tilde{\lambda}(t)x+\tilde{x}(t) \right)
=\tilde{\epsilon}(t)+ Q, \\\notag 
	&\tilde{\lambda}(t)=\lambda_n^{-1}{\lambda \left(\lambda_n^2t \right)},\   t\in \left[0,\lambda_n^{-2}t_n \right],   \\\notag
	&\tilde{x}\left(\lambda_n^{-2}t_n\right)=\tilde{\xi} \left(\lambda_n^{-2}t_n \right)=0,\  \frac{ \left|\tilde{\xi}(t) \right|}{\tilde{\lambda}(t)}
