\label{posit}
The following four properties hold:
	\begin{enumerate}
		\item ${L}_{+}$ is a self-adjoint operator and $\sigma_{ess}({L}_{+}) = [1, \infty)$.


		\item $L_{+}$ has a unique negative eigenvalue $\lambda$ associated with an eigenfunction $\chi\in H^1$. 

        \item $( {L}_{-} u,u )_{L^2}\geq 0$ for any real-valued $u\in H^1$.

		\item There exists a constant $c_d>0$ such that if $u\in H^1(\mathbb{R}^d)$ is real-valued and satisfies $u\perp_{L^2}\{\chi,\partial_{x_1}Q,\cdots,\partial_{x_d}Q\}$, then $( {L}_{+} u,u )_{L^2}\geq c_d\|u\|^2_{H^1}$.
	\end{enumerate}

For any $p\in (1,\infty)$ and integer $k\geq0$, we have
\begin{equation}\label{equ:nablakchi}
    \||\nabla|^k \chi\|_{L^p}\lesssim_{p,k}1.
\end{equation}
Moreover, there exists $\delta_0>0$ such that
\begin{equation}\label{equ:chidecay}
    |\chi(x)|\lesssim e^{-\delta_0|x|}.
\end{equation}

\label{modulation}
 Let $u\in L^2(\mathbb{R}^d)$. There exists $\alpha > 0$ sufficiently small such that if there exist $\lambda_{0} > 0$, $\gamma_0\in [0,2\pi]$, $x_{0} \in \mathbb{R}^d$, and $\xi_{0} \in \mathbb{R}^d$ satisfying 
\begin{equation*} 
\| e^{i \gamma_{0}} e^{ix \cdot \xi_{0}} \lambda_{0}^{\frac{d}{2}} u (\lambda_{0} x + x_{0}) -
Q(x) \|_{L^{2}} \leq \alpha,
\end{equation*}
then there exist unique parameters $\lambda>0$, $\gamma\in\mathbb{R}$,
$\tilde x,\xi\in\mathbb{R}^d$ in a sufficiently small neighborhood of
$(\lambda_0,\gamma_0,x_0,\xi_0)$, measured by the left-hand side of
\eqref{f4.4}, such that if 
\begin{equation*} 
\epsilon(x):= e^{i \gamma} e^{ix \cdot \xi} \lambda^{d/2} u \left(\lambda x + \tilde{x} \right) - Q(x),
\end{equation*}
then the following orthogonality conditions hold: 
\begin{align}\label{f4.3}
( \epsilon,\chi  )_{L^2}
&= ( \epsilon,i\chi  )_{L^2}
=( \epsilon,\partial_{x_j}Q  )_{L^2}=( \epsilon,i\partial_{x_j}Q  )_{L^2}=0, \quad j=1,\cdots,d,
\end{align}
and, with the phase chosen near
$\gamma_0+\lambda_0^{-1}\xi_0\cdot(\tilde x-x_0)$, we have
\begin{align}\label{f4.4}
\aligned
& \|\epsilon\|_{L^2} +   \left|\frac{\lambda}{\lambda_{0}} - 1 \right|
+  \left|\gamma - \gamma_{0} - \frac{\xi_{0}}{\lambda_{0}} \cdot \left(\tilde{x} - x_{0} \right) \right|
 +  \left|\xi - \frac{\lambda}{\lambda_{0}} \xi_{0} \right| +  \left|\frac{\tilde{x} - x_{0}}{\lambda_{0}} \right|  \\
\lesssim& \| e^{i \gamma_{0}} e^{ix \cdot \xi_{0}} \lambda_{0}^{d/2} u \left(\lambda_{0} x + x_{0} \right) - Q(x) \|_{L^{2}}.
\endaligned
\end{align}
